// 用于安全处理私钥的工具类
import { ethers } from 'ethers';

// 从环境变量获取主密钥 - 在实际生产环境中，这应该存储在安全的环境变量或密钥管理系统中
const MASTER_KEY = process.env.REACT_APP_MASTER_KEY || 'default-master-key-do-not-use-in-production';

// 从环境变量获取默认密码，如果未设置则使用备用密码
export const DEFAULT_PASSWORD = process.env.REACT_APP_DEFAULT_PASSWORD || 'default-secure-password-123';

// 密钥派生函数 - 从主密钥派生实际用于加密的密钥
const deriveSecretKey = (masterKey, salt = '') => {
  // 简单的密钥派生实现，实际应用中应使用PBKDF2等标准算法
  const combinedInput = masterKey + salt;
  let derivedKey = '';
  
  // 简单的哈希迭代生成密钥
  for (let i = 0; i < 1000; i++) {
    const hashInput = derivedKey + combinedInput + i;
    // 使用简单的字符串哈希方法
    let hash = 0;
    for (let j = 0; j < hashInput.length; j++) {
      const char = hashInput.charCodeAt(j);
      hash = ((hash << 5) - hash) + char;
      hash = hash & hash; // 转换为32位整数
    }
    derivedKey += hash.toString(16);
  }
  
  // 截取适当长度
  return derivedKey.slice(0, 32);
};

// 加密当前使用的默认密码
const encryptDefaultPassword = () => {
  const derivedKey = deriveSecretKey(MASTER_KEY, 'password-encryption-salt');
  return encryptWithKey(DEFAULT_PASSWORD, derivedKey);
};

// 解密当前使用的默认密码
const decryptDefaultPassword = (encryptedPassword) => {
  const derivedKey = deriveSecretKey(MASTER_KEY, 'password-encryption-salt');
  return decryptWithKey(encryptedPassword, derivedKey);
};

// 使用派生密钥进行加密
const encryptWithKey = (data, key) => {
  if (!data) return '';
  try {
    // 创建一个简单的派生密钥
    const keyBytes = new TextEncoder().encode(key.repeat(2).slice(0, 32));
    // 用密钥的前16个字符作为IV
    const ivBytes = new TextEncoder().encode(key.slice(0, 16).padEnd(16, '0'));
    
    // 转换为十六进制字符串
    const dataBytes = new TextEncoder().encode(data);
    
    // 简单的XOR加密，仅用于本地临时存储
    const encryptedBytes = new Uint8Array(dataBytes.length);
    for (let i = 0; i < dataBytes.length; i++) {
      encryptedBytes[i] = dataBytes[i] ^ keyBytes[i % keyBytes.length] ^ ivBytes[i % ivBytes.length];
    }
    
    // 转换为Base64
    return btoa(String.fromCharCode(...encryptedBytes));
  } catch (error) {
    console.error('加密失败:', error);
    return '';
  }
};

// 使用派生密钥进行解密
const decryptWithKey = (encryptedData, key) => {
  if (!encryptedData) return '';
  try {
    // 解析Base64
    const encryptedBytes = new Uint8Array(
      atob(encryptedData).split('').map(c => c.charCodeAt(0))
    );
    
    // 创建一个简单的派生密钥
    const keyBytes = new TextEncoder().encode(key.repeat(2).slice(0, 32));
    // 用密钥的前16个字符作为IV
    const ivBytes = new TextEncoder().encode(key.slice(0, 16).padEnd(16, '0'));
    
    // 解密
    const decryptedBytes = new Uint8Array(encryptedBytes.length);
    for (let i = 0; i < encryptedBytes.length; i++) {
      decryptedBytes[i] = encryptedBytes[i] ^ keyBytes[i % keyBytes.length] ^ ivBytes[i % ivBytes.length];
    }
    
    // 转换回字符串
    return new TextDecoder().decode(decryptedBytes);
  } catch (error) {
    console.error('解密失败:', error);
    return '';
  }
};

// 用于加密私钥的函数 - 使用派生密钥
export const encryptPrivateKey = (privateKey, password) => {
  if (!privateKey) return '';
  let result = '';
  try {
    // 从密码派生密钥
    const derivedKey = deriveSecretKey(password, 'private-key-encryption');
    // 使用派生密钥加密
    result = encryptWithKey(privateKey, derivedKey);
    return result;
  } catch (error) {
    console.error('加密失败:', error);
    return '';
  } finally {
    // 尝试清除敏感数据
    if (result && privateKey) {
      // 覆盖原始私钥字符串
      privateKey = '0'.repeat(privateKey.length);
    }
  }
};

// 用于解密私钥的函数 - 使用派生密钥
export const decryptPrivateKey = (encryptedData, password) => {
  if (!encryptedData) return '';
  try {
    // 从密码派生密钥
    const derivedKey = deriveSecretKey(password, 'private-key-encryption');
    // 使用派生密钥解密
    return decryptWithKey(encryptedData, derivedKey);
  } catch (error) {
    console.error('解密失败:', error);
    return '';
  }
};

// 存储已加密的默认密码
export const ENCRYPTED_DEFAULT_PASSWORD = encryptDefaultPassword();

// 获取解密后的默认密码 - 实际使用时需要验证身份
export const getDecryptedDefaultPassword = () => {
  return decryptDefaultPassword(ENCRYPTED_DEFAULT_PASSWORD);
};

// 修改后的processPrivateKey函数，使用解密后的默认密码
export const processPrivateKey = (privateKey, password = null) => {
  // 如果未提供密码，使用解密后的默认密码
  const actualPassword = password || getDecryptedDefaultPassword();
  
  if (!privateKey) return '';
  
  let result = '';
  let tempDecrypted = '';
  
  try {
    // 检查是否像是Base64格式的加密私钥
    const isLikelyEncrypted = /^[A-Za-z0-9+/=]+$/.test(privateKey.trim()) && 
                             !privateKey.startsWith('0x') &&
                             privateKey.length > 42;
    
    if (isLikelyEncrypted) {
      console.log('检测到可能是加密的私钥，尝试解密');
      tempDecrypted = decryptPrivateKey(privateKey, actualPassword);
      
      // 验证解密结果是否是有效的私钥
      if (isValidPrivateKey(tempDecrypted)) {
        console.log('成功解密私钥');
        result = tempDecrypted;
        return result;
      } else {
        console.log('解密结果不是有效私钥，尝试其他处理方式');
        // 立即清除失败的解密结果
        tempDecrypted = '0'.repeat(tempDecrypted.length);
      }
    }
    
    // 检查是否已经是有效的私钥
    if (isValidPrivateKey(privateKey)) {
      result = privateKey;
      return result;
    }
    
    // 如果不是加密的也不是有效的，尝试修复常见问题
    // 1. 移除前后空格
    const trimmed = privateKey.trim();
    
    // 2. 添加0x前缀（如果没有）
    const withPrefix = trimmed.startsWith('0x') ? trimmed : `0x${trimmed}`;
    
    if (isValidPrivateKey(withPrefix)) {
      result = withPrefix;
      return result;
    }
    
    // 如果所有尝试都失败，返回原始输入
    result = privateKey;
    return result;
  } catch (error) {
    console.error('处理私钥时出错:', error);
    result = privateKey;
    return result;
  } finally {
    // 清除敏感数据
    if (tempDecrypted) {
      tempDecrypted = '0'.repeat(tempDecrypted.length);
    }
  }
};

// 处理从CSV导入的私钥列表
export const processImportedKeys = (keysText, password = null) => {
  // 如果未提供密码，使用解密后的默认密码
  let actualPassword = password || getDecryptedDefaultPassword();
  
  if (!keysText) return [];
  
  try {
    // 创建一个用于存储处理后的私钥的数组
    const processedKeys = [];
    
    // 尝试从CSV注释中提取密码
    if (keysText.includes('# 解密密码:')) {
      const passwordLine = keysText.split('\n').find(line => line.includes('# 解密密码:'));
      if (passwordLine) {
        const extractedPassword = passwordLine.split('# 解密密码:')[1]?.trim();
        if (extractedPassword && extractedPassword !== 'undefined') {
          console.log('从CSV文件中提取到密码');
          actualPassword = extractedPassword;
        }
      }
    }
    
    // 确保密码不为undefined
    if (!actualPassword || actualPassword === 'undefined') {
      actualPassword = DEFAULT_PASSWORD || 'default-secure-password-123';
    }
    
    // 检查是否是CSV格式
    const isCSV = keysText.includes(',');
    
    if (isCSV) {
      // 尝试解析CSV
      const lines = keysText.split('\n').filter(line => 
        line.trim() && !line.startsWith('#')
      );
      
      // 检查是否有标题行
      const hasHeader = lines[0].includes('地址') || 
                        lines[0].includes('私钥') || 
                        lines[0].toLowerCase().includes('address');
      
      // 从标题行找出私钥和加密私钥所在列
      let privateKeyIndex = 2; // 默认假设第3列是私钥
      let encryptedKeyIndex = -1; // 加密私钥列索引
      let formatIndex = -1; // 格式列索引
      
      if (hasHeader) {
        const headers = lines[0].split(',').map(h => h.trim().replace(/"/g, ''));
        
        // 查找列索引
        privateKeyIndex = headers.findIndex(h => 
          h.includes('私钥') || h.toLowerCase().includes('private')
        );
        encryptedKeyIndex = headers.findIndex(h => 
          h.includes('加密私钥') || h.toLowerCase().includes('encrypted')
        );
        formatIndex = headers.findIndex(h => 
          h === '格式' || h.toLowerCase() === 'format'
        );
        
        if (privateKeyIndex === -1) privateKeyIndex = 2; // 找不到就用默认值
      }
      
      // 解析每一行
      const startIndex = hasHeader ? 1 : 0;
      
      for (let i = startIndex; i < lines.length; i++) {
        const line = lines[i].trim();
        if (!line) continue;
        
        try {
          const columns = line.split(',').map(col => col.trim().replace(/"/g, ''));
          
          // 获取私钥和加密私钥
          let privateKey = columns[privateKeyIndex];
          const encryptedKey = encryptedKeyIndex >= 0 ? columns[encryptedKeyIndex] : '';
          const format = formatIndex >= 0 ? columns[formatIndex] : '';
          
          // 处理逻辑:
          // 1. 首先尝试直接使用原始私钥
          // 2. 如果原始私钥无效，但有加密私钥，尝试解密
          // 3. 否则根据格式处理
          
          let validPrivateKey = null;
          
          // 尝试使用原始私钥
          if (privateKey && isValidPrivateKey(privateKey)) {
            validPrivateKey = privateKey;
          } 
          // 尝试解密加密私钥
          else if (encryptedKey && encryptedKey.length > 0) {
            try {
              const decryptedKey = decryptPrivateKey(encryptedKey, actualPassword);
              if (isValidPrivateKey(decryptedKey)) {
                validPrivateKey = decryptedKey;
              }
            } catch (decryptError) {
              console.warn(`第 ${i+1} 行: 解密加密私钥失败，尝试其他方法`);
            }
          }
          // 根据格式处理
          else if (format === 'encrypted') {
            try {
              const decryptedKey = decryptPrivateKey(privateKey, actualPassword);
              if (isValidPrivateKey(decryptedKey)) {
                validPrivateKey = decryptedKey;
              }
            } catch (formatDecryptError) {
              console.warn(`第 ${i+1} 行: 根据格式解密失败`);
            }
          } 
          // 尝试智能处理
          else {
            try {
              const processedKey = processPrivateKey(privateKey, actualPassword);
              if (isValidPrivateKey(processedKey)) {
                validPrivateKey = processedKey;
              }
            } catch (processError) {
              console.warn(`第 ${i+1} 行: 智能处理私钥失败`);
            }
          }
          
          // 添加有效私钥到结果
          if (validPrivateKey) {
            processedKeys.push(validPrivateKey);
            // 立即清除临时变量中的明文私钥
            if (privateKey) columns[privateKeyIndex] = '0'.repeat(privateKey.length);
            if (encryptedKey) columns[encryptedKeyIndex] = '0'.repeat(encryptedKey.length);
            validPrivateKey = '0'.repeat(validPrivateKey.length);
          }
        } catch (lineError) {
          console.error(`处理第 ${i+1} 行出错:`, lineError);
        }
      }
    } else {
      // 普通文本格式，每行一个私钥
      const lines = keysText.split('\n');
      for (let i = 0; i < lines.length; i++) {
        const line = lines[i].trim();
        if (!line) continue;
        
        let privateKey = processPrivateKey(line, actualPassword);
        if (privateKey && isValidPrivateKey(privateKey)) {
          processedKeys.push(privateKey);
          // 立即清除临时变量中的明文私钥
          lines[i] = '0'.repeat(lines[i].length);
        }
      }
    }
    
    // 清除原始输入
    if (typeof keysText === 'string') {
      // 这种方式不能真正清除原始变量，但可以尽量减少敏感信息在内存中的存在
      keysText = keysText.replace(/./g, '0');
    }
    
    return processedKeys;
  } catch (error) {
    console.error('处理导入的私钥出错:', error);
    return [];
  } finally {
    // 强制触发垃圾回收，尝试清除临时变量
    if (global.gc) {
      global.gc();
    }
  }
};

// 用于掩码显示私钥的函数
export const maskPrivateKey = (privateKey, visibleChars = 4) => {
  if (!privateKey) return '';
  const start = privateKey.substring(0, visibleChars);
  const end = privateKey.substring(privateKey.length - visibleChars);
  return `${start}...${end}`;
};

// 清除内存中的私钥
export const clearPrivateKeyFromMemory = (privateKeyVar) => {
  if (typeof privateKeyVar === 'string') {
    // 覆盖内存中的字符串
    privateKeyVar = '0'.repeat(privateKeyVar.length);
    privateKeyVar = null;
  }
  // 触发垃圾回收
  if (global.gc) {
    global.gc();
  }
};

// 加密CSV内容
export const encryptCSVContent = (csvContent, password = null) => {
  const actualPassword = password || getDecryptedDefaultPassword();
  return encryptPrivateKey(csvContent, actualPassword);
};

// 生成安全的CSV文件
export const generateSecureCSV = (headers, data, includePrivateKeys = true) => {
  // 创建CSV内容，根据includePrivateKeys决定是否包含私钥
  const csvRows = [
    headers.join(',')
  ];
  
  data.forEach(row => {
    const processedRow = { ...row };
    // 如果不包含私钥，则掩码处理
    if (!includePrivateKeys && processedRow.privateKey) {
      processedRow.privateKey = maskPrivateKey(processedRow.privateKey);
    }
    // 处理CSV行
    csvRows.push(
      Object.values(processedRow).map(value => `"${value}"`).join(',')
    );
  });
  
  return csvRows.join('\n');
};

// 验证私钥是否有效
export const isValidPrivateKey = (key) => {
  try {
    if (!key) return false;
    
    // 如果私钥不是以0x开头，添加前缀
    const formattedKey = key.startsWith('0x') ? key : `0x${key}`;
    
    // 使用ethers验证私钥
    new ethers.Wallet(formattedKey);
    return true;
  } catch (error) {
    return false;
  }
};

// 创建安全钱包
export const createSecureWallet = () => {
  try {
    // 创建随机钱包
    const wallet = ethers.Wallet.createRandom();
    
    // 获取必要信息并立即加密私钥
    const address = wallet.address;
    const mnemonic = wallet.mnemonic.phrase;
    const privateKey = wallet.privateKey;
    const encryptedPrivateKey = encryptPrivateKey(privateKey, DEFAULT_PASSWORD);
    
    // 返回包含已加密私钥的结果
    return {
      address: address,
      mnemonic: mnemonic,
      privateKey: privateKey,
      encryptedPrivateKey: encryptedPrivateKey
    };
  } finally {
    // 尝试清除可能留在内存中的敏感数据
    // 注意：这不能完全保证垃圾回收会立即发生
    if (global.gc) {
      global.gc();
    }
  }
};

// 安全使用钱包进行签名，确保私钥不会在内存中持久存在
export const secureSignTransaction = async (encryptedPrivateKey, transactionData, password = null) => {
  const actualPassword = password || getDecryptedDefaultPassword();
  let decryptedKey = null;
  
  try {
    // 解密私钥
    decryptedKey = decryptPrivateKey(encryptedPrivateKey, actualPassword);
    if (!isValidPrivateKey(decryptedKey)) {
      throw new Error('无效的私钥或密码不正确');
    }
    
    // 创建钱包实例
    const wallet = new ethers.Wallet(decryptedKey);
    
    // 签名交易
    const signedTx = await wallet.signTransaction(transactionData);
    
    return signedTx;
  } catch (error) {
    console.error('签名交易失败:', error);
    throw error;
  } finally {
    // 清除内存中的私钥
    if (decryptedKey) {
      decryptedKey = '0'.repeat(decryptedKey.length);
      decryptedKey = null;
    }
    
    // 强制垃圾回收
    if (global.gc) {
      global.gc();
    }
  }
}; 