// ==================== 工具函数 ====================
function formatBigInt(value, decimals = 18) {
  if (!value || value.toString() === '0') return '0';
  try {
    return ethers.formatUnits(value, decimals);
  } catch (err) {
    console.error("格式化BigInt失败:", err);
    return '0';
  }
}

function getRandomAmount(min, max, decimals = 6) {
  const random = Math.random() * (parseFloat(max) - parseFloat(min)) + parseFloat(min);
  return parseFloat(random.toFixed(decimals));
}

// 重试机制函数
const withRetry = async (operation, maxRetries = 3, delay = 1000) => {
  for (let attempt = 1; attempt <= maxRetries; attempt++) {
    try {
      return await operation();
    } catch (error) {
      console.log(`尝试 ${attempt}/${maxRetries} 失败:`, error.message);
      
      if (attempt === maxRetries) {
        throw error;
      }
      
      // 指数退避延迟
      const waitTime = delay * Math.pow(2, attempt - 1);
      console.log(`等待 ${waitTime}ms 后重试...`);
      await new Promise(resolve => setTimeout(resolve, waitTime));
    }
  }
};

function formatPrice(price) {
  if (!price) return '0';
  
  try {
    // 确保price是一个有效的数字
    const num = parseFloat(price);
    if (isNaN(num)) return '0';
    
    // 对于非常小的数字，保留更多小数位，避免显示为0
    if (num < 0.00001) {
      return num.toFixed(18).replace(/0+$/, '');
    }
    
    // 正常情况下返回数字的字符串表示
    return num.toString();
  } catch (err) {
    console.error("格式化价格出错:", err);
    return '0';
  }
}

// 添加获取BNB余额的辅助函数
async function getBNBBalance(provider, address) {
  try {
    const balance = await provider.getBalance(address);
    return ethers.formatEther(balance);
  } catch (err) {
    console.error("获取BNB余额失败:", err);
    return "0";
  }
}

// 添加获取USD1余额的辅助函数
async function getUSD1Balance(provider, address) {
  try {
    // 创建合约实例
    const tokenContract = new ethers.Contract(TOKENS.USD1.address, ERC20_ABI, provider);
    
    // 添加重试机制
    let balance;
    for (let i = 0; i < 3; i++) {
      try {
        balance = await tokenContract.balanceOf(address);
        break; // 如果成功，跳出循环
      } catch (error) {
        console.warn(`获取USD1余额尝试 ${i+1}/3 失败:`, error.message);
        if (i === 2) throw error; // 最后一次尝试仍失败，抛出错误
        await new Promise(r => setTimeout(r, 1000)); // 等待1秒再重试
      }
    }
    
    return ethers.formatUnits(balance, TOKENS.USD1.decimals);
  } catch (err) {
    console.error("获取USD1余额失败:", err);
    return "0";
  }
}

// 添加从其他钱包转入BNB的辅助函数
async function transferBNBFromOtherWallet(provider, fromWallet, toAddress, requiredAmount) {
  try {
    const tx = await fromWallet.sendTransaction({
      to: toAddress,
      value: ethers.parseEther(requiredAmount.toString()),
      gasLimit: 21000
    });
    
    await tx.wait();
    console.log(`从钱包 ${fromWallet.address} 转入 ${requiredAmount} BNB 到 ${toAddress}`);
    return true;
  } catch (err) {
    console.error("BNB转账失败:", err);
    return false;
  }
}

// 添加从其他钱包转入USD1的辅助函数
async function transferUSD1FromOtherWallet(provider, fromWallet, toAddress, requiredAmount) {
  try {
    const usd1Contract = new ethers.Contract(
      TOKENS.USD1.address,
      ERC20_ABI,
      fromWallet
    );
    
    const tx = await usd1Contract.transfer(
      toAddress, 
      ethers.parseUnits(requiredAmount.toString(), 18)
    );
    
    await tx.wait();
    return true;
  } catch (err) {
    console.error("转账USD1失败:", err);
    return false;
  }
}



