/**
 * 部署以太坊批量转账合约
 * @param {ethers.Signer} signer - 签名者对象
 * @returns {Promise<{address: string, contract: ethers.Contract}>} 部署结果
 */
export async function deployEthBatchContract(signer) {
  try {
    console.log('🚀 开始部署以太坊批量转账合约...');
    
    // 创建合约工厂
    const contractFactory = new ethers.ContractFactory(
      CONTRACT_ABI,
      CONTRACT_BYTECODE,
      signer
    );
    
    // 估算部署费用
    const deploymentData = contractFactory.getDeployTransaction();
    const gasEstimate = await signer.estimateGas(deploymentData);
    const feeData = await signer.provider.getFeeData();
    
    const deploymentCost = gasEstimate * feeData.gasPrice;
    const deploymentCostEth = ethers.formatEther(deploymentCost);
    
    console.log(`📊 预估部署费用: ${deploymentCostEth} ETH`);
    console.log(`⛽ 预估Gas用量: ${gasEstimate.toString()}`);
    
    // 部署合约
    console.log('⏳ 正在部署合约...');
    const contract = await contractFactory.deploy({
      gasLimit: gasEstimate + ethers.toBigInt(50000), // 增加一些gas缓冲
      gasPrice: feeData.gasPrice
    });
    
    console.log(`📝 合约部署交易哈希: ${contract.deploymentTransaction().hash}`);
    console.log('⌛ 等待合约部署确认...');
    
    // 等待部署确认
    const deployedContract = await contract.waitForDeployment();
    const contractAddress = await deployedContract.getAddress();
    
    console.log('✅ 合约部署成功!');
    console.log(`📍 合约地址: ${contractAddress}`);
    console.log(`🔗 在Etherscan查看: https://etherscan.io/address/${contractAddress}`);
    
    return {
      address: contractAddress,
      contract: deployedContract,
      txHash: contract.deploymentTransaction().hash
    };
    
  } catch (error) {
    console.error('❌ 合约部署失败:', error);
    throw error;
  }
}

/**
 * 验证合约是否部署成功
 * @param {string} contractAddress - 合约地址
 * @param {ethers.Provider} provider - 提供者对象
 * @returns {Promise<boolean>} 验证结果
 */
export async function verifyContractDeployment(contractAddress, provider) {
  try {
    const code = await provider.getCode(contractAddress);
    return code !== '0x';
  } catch (error) {
    console.error('验证合约部署失败:', error);
    return false;
  }
}

/**
 * 获取合约实例
 * @param {string} contractAddress - 合约地址
 * @param {ethers.Signer|ethers.Provider} signerOrProvider - 签名者或提供者
 * @returns {ethers.Contract} 合约实例
 */
export function getEthBatchContract(contractAddress, signerOrProvider) {
  return new ethers.Contract(contractAddress, CONTRACT_ABI, signerOrProvider);
}

