// 用于显示消息提示的工具类

/**
 * 显示消息提示
 * @param {string} content - 消息内容
 * @param {string} type - 消息类型: 'info', 'success', 'warning', 'error'
 * @param {number} duration - 显示时长(毫秒)
 */
export const showMessage = (content, type = 'info', duration = 3000) => {
  // 创建消息元素
  const messageElement = document.createElement('div');
  messageElement.textContent = content;
  messageElement.style.position = 'fixed';
  messageElement.style.zIndex = '9999';
  messageElement.style.top = '20px';
  messageElement.style.left = '50%';
  messageElement.style.transform = 'translateX(-50%)';
  messageElement.style.padding = '10px 20px';
  messageElement.style.borderRadius = '4px';
  messageElement.style.boxShadow = '0 2px 8px rgba(0,0,0,0.2)';
  messageElement.style.minWidth = '200px';
  messageElement.style.textAlign = 'center';
  
  // 根据类型设置样式
  switch (type) {
    case 'success':
      messageElement.style.backgroundColor = '#e8f5e9';
      messageElement.style.color = '#2e7d32';
      messageElement.style.border = '1px solid #c8e6c9';
      break;
    case 'warning':
      messageElement.style.backgroundColor = '#fff8e1';
      messageElement.style.color = '#f57f17';
      messageElement.style.border = '1px solid #ffecb3';
      break;
    case 'error':
      messageElement.style.backgroundColor = '#ffebee';
      messageElement.style.color = '#c62828';
      messageElement.style.border = '1px solid #ffcdd2';
      break;
    default: // info
      messageElement.style.backgroundColor = '#e3f2fd';
      messageElement.style.color = '#0d47a1';
      messageElement.style.border = '1px solid #bbdefb';
  }
  
  // 添加到文档中
  document.body.appendChild(messageElement);
  
  // 设置自动消失
  setTimeout(() => {
    // 添加淡出效果
    messageElement.style.transition = 'opacity 0.5s ease';
    messageElement.style.opacity = '0';
    
    setTimeout(() => {
      // 从DOM中移除
      if (messageElement.parentNode) {
        document.body.removeChild(messageElement);
      }
    }, 500);
  }, duration);
  
  // 返回消息元素，允许提前关闭
  return messageElement;
};

/**
 * 弹出确认对话框
 * @param {string} message - 确认消息
 * @returns {Promise<boolean>} - 用户选择结果
 */
export const showConfirm = (message) => {
  return new Promise((resolve) => {
    // 使用浏览器原生confirm
    const result = window.confirm(message);
    resolve(result);
  });
};

/**
 * 创建加载指示器
 * @returns {Object} - 包含show和hide方法的对象
 */
export const createLoadingIndicator = () => {
  let loadingElement = null;
  
  return {
    show: (message = '处理中...') => {
      // 如果已经存在，先移除
      if (loadingElement && loadingElement.parentNode) {
        document.body.removeChild(loadingElement);
      }
      
      // 创建加载元素
      loadingElement = document.createElement('div');
      loadingElement.style.position = 'fixed';
      loadingElement.style.top = '0';
      loadingElement.style.left = '0';
      loadingElement.style.width = '100%';
      loadingElement.style.height = '100%';
      loadingElement.style.backgroundColor = 'rgba(0,0,0,0.5)';
      loadingElement.style.display = 'flex';
      loadingElement.style.alignItems = 'center';
      loadingElement.style.justifyContent = 'center';
      loadingElement.style.zIndex = '10000';
      
      // 创建加载内容
      const content = document.createElement('div');
      content.style.backgroundColor = 'white';
      content.style.padding = '20px 40px';
      content.style.borderRadius = '8px';
      content.style.boxShadow = '0 4px 12px rgba(0,0,0,0.15)';
      content.style.display = 'flex';
      content.style.flexDirection = 'column';
      content.style.alignItems = 'center';
      
      // 创建加载图标
      const spinner = document.createElement('div');
      spinner.style.width = '40px';
      spinner.style.height = '40px';
      spinner.style.border = '4px solid #f3f3f3';
      spinner.style.borderTop = '4px solid #3498db';
      spinner.style.borderRadius = '50%';
      spinner.style.marginBottom = '15px';
      spinner.style.animation = 'spin 1s linear infinite';
      
      // 添加动画样式
      const style = document.createElement('style');
      style.textContent = '@keyframes spin { 0% { transform: rotate(0deg); } 100% { transform: rotate(360deg); } }';
      document.head.appendChild(style);
      
      // 添加文本
      const text = document.createElement('div');
      text.textContent = message;
      
      // 组装并添加到DOM
      content.appendChild(spinner);
      content.appendChild(text);
      loadingElement.appendChild(content);
      document.body.appendChild(loadingElement);
    },
    
    hide: () => {
      if (loadingElement && loadingElement.parentNode) {
        document.body.removeChild(loadingElement);
        loadingElement = null;
      }
    }
  };
}; 