// Format BigInt to readable decimal
function formatBigInt(value, decimals = 18) {
  try {
    const formatted = ethers.formatUnits(value, decimals);
    return parseFloat(formatted).toFixed(6);
  } catch (err) {
    return '0';
  }
}

// Format price for display
function formatPrice(price) {
  const num = parseFloat(price);
  if (num === 0 || isNaN(num)) return '0';
  
  // 处理科学计数法和极小数字，确保显示完整的小数而不是科学计数法
  if (num < 0.000000000001) return num.toFixed(15);  // 15位小数
  if (num < 0.00000000001) return num.toFixed(14);   // 14位小数
  if (num < 0.0000000001) return num.toFixed(13);    // 13位小数
  if (num < 0.000000001) return num.toFixed(12);     // 12位小数
  if (num < 0.00000001) return num.toFixed(11);      // 11位小数
  if (num < 0.0000001) return num.toFixed(10);       // 10位小数
  if (num < 0.000001) return num.toFixed(9);         // 9位小数
  if (num < 0.00001) return num.toFixed(8);          // 8位小数
  if (num < 0.0001) return num.toFixed(7);           // 7位小数
  if (num < 0.001) return num.toFixed(6);            // 6位小数
  if (num < 0.01) return num.toFixed(5);             // 5位小数
  if (num < 0.1) return num.toFixed(4);              // 4位小数
  if (num < 1) return num.toFixed(3);                // 3位小数
  if (num < 1000) return num.toFixed(2);             // 2位小数
  
  // 对于大数字，使用千分位分隔符
  return num.toLocaleString('en-US', {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2
  });
}

// Calculate sqrt price from token amounts (V3 specific)
function calculateSqrtPriceX96(token0Amount, token1Amount, decimals0, decimals1) {
  try {
    const price = (parseFloat(token1Amount) * Math.pow(10, decimals0)) / 
                  (parseFloat(token0Amount) * Math.pow(10, decimals1));
    const sqrtPrice = Math.sqrt(price);
    const sqrtPriceX96 = BigInt(Math.floor(sqrtPrice * Math.pow(2, 96)));
    return sqrtPriceX96;
  } catch (err) {
    return BigInt(0);
  }
}

// Convert sqrt price to human readable price
function sqrtPriceX96ToPrice(sqrtPriceX96, decimals0, decimals1) {
  try {
    console.log('sqrtPriceX96ToPrice 输入参数:', {
      sqrtPriceX96: sqrtPriceX96.toString(),
      decimals0,
      decimals1
    });
    
    // Convert to string and use mathematical calculation
    const sqrtPriceStr = sqrtPriceX96.toString();
    
    // Calculate sqrtPrice = sqrtPriceX96 / 2^96
    // 2^96 = 79228162514264337593543950336
    const Q96 = 79228162514264337593543950336;
    const sqrtPriceDecimal = parseFloat(sqrtPriceStr) / Q96;
    
    // Calculate price = sqrtPrice^2
    const price = Math.pow(sqrtPriceDecimal, 2);
    
    // Adjust for token decimals
    const decimalAdjustment = Math.pow(10, Number(decimals0) - Number(decimals1));
    const adjustedPrice = price * decimalAdjustment;
    
    console.log('sqrtPriceX96ToPrice 计算结果:', {
      sqrtPriceDecimal,
      priceBeforeAdjustment: price,
      decimalAdjustment,
      finalPrice: adjustedPrice
    });
    
    return adjustedPrice;
  } catch (err) {
    console.error('sqrtPriceX96ToPrice 计算失败:', err);
    return 0;
  }
}

// Get random amount with proper decimals
function getRandomAmount(min, max, decimals = 18) {
  const randomFloat = Math.random() * (max - min) + min;
  return ethers.parseUnits(randomFloat.toFixed(decimals), decimals);
}

// Calculate V3 pool liquidity value in USD
async function calculateV3PoolLiquidityUSD(poolContract, token0Contract, token1Contract, ethPrice) {
  try {
    const poolAddress = await poolContract.getAddress();
    
    const [token0Balance, token1Balance, token0Decimals, token1Decimals, token0Address, token1Address, slot0] = await Promise.all([
      token0Contract.balanceOf(poolAddress),
      token1Contract.balanceOf(poolAddress),
      token0Contract.decimals(),
      token1Contract.decimals(),
      token0Contract.getAddress(),
      token1Contract.getAddress(),
      poolContract.slot0()
    ]);

    // Format balances with correct decimals
    const token0BalanceFormatted = parseFloat(ethers.formatUnits(token0Balance, token0Decimals));
    const token1BalanceFormatted = parseFloat(ethers.formatUnits(token1Balance, token1Decimals));
    
    // Calculate price using pool balances - 直接计算USD价格
    let priceUSD = 0;
    let estimatedUSDValue = 0;
    
    if (token0Address.toLowerCase() === WETH_ADDRESS.toLowerCase()) {
      // Token0 is WETH, Token1 is the project token
      // 项目代币USD价格 = (WETH余额 * ETH的USD价格) / 项目代币余额
      if (token1BalanceFormatted > 0) {
        priceUSD = (token0BalanceFormatted * ethPrice) / token1BalanceFormatted;
      }
      // Calculate USD value: (ETH balance * ETH price) * 2 (total liquidity)
      estimatedUSDValue = token0BalanceFormatted * ethPrice * 2;
      console.log(`WETH是Token0: WETH余额=${token0BalanceFormatted}, 项目代币余额=${token1BalanceFormatted}, 项目代币USD价格=$${priceUSD}`);
    } else if (token1Address.toLowerCase() === WETH_ADDRESS.toLowerCase()) {
      // Token1 is WETH, Token0 is the project token  
      // 项目代币USD价格 = (WETH余额 * ETH的USD价格) / 项目代币余额
      if (token0BalanceFormatted > 0) {
        priceUSD = (token1BalanceFormatted * ethPrice) / token0BalanceFormatted;
      }
      // Calculate USD value: (ETH balance * ETH price) * 2 (total liquidity)
      estimatedUSDValue = token1BalanceFormatted * ethPrice * 2;
      console.log(`WETH是Token1: WETH余额=${token1BalanceFormatted}, 项目代币余额=${token0BalanceFormatted}, 项目代币USD价格=$${priceUSD}`);
    }
    
    console.log(`V3 Pool Liquidity: Token0=${token0BalanceFormatted}, Token1=${token1BalanceFormatted}, USD Value=${estimatedUSDValue}`);
    
    return {
      liquidity: (token0Balance + token1Balance).toString(),
      liquidityFormatted: `${token0BalanceFormatted.toFixed(6)} / ${token1BalanceFormatted.toFixed(6)}`,
      price: priceUSD.toString(),
      priceFormatted: formatPrice(priceUSD),
      estimatedUSDValue: estimatedUSDValue
    };
  } catch (err) {
    console.error('Error calculating V3 pool liquidity:', err);
    return {
      liquidity: '0',
      liquidityFormatted: '0',
      price: '0',
      priceFormatted: '0',
      estimatedUSDValue: 0
    };
  }
}

