  // 快速检查交易状态 - 每500ms检查一次（每秒2次）
  const fastWaitForTransaction = async (txHash, timeoutSeconds = 60) => {
    const startTime = Date.now();
    const timeout = timeoutSeconds * 1000;
    
    return new Promise((resolve, reject) => {
      let intervalId;
      
      const checkStatus = async () => {
        try {
          // 检查交易是否上链
          const receipt = await rpcProvider.getTransactionReceipt(txHash);
          
          if (receipt) {
            const endTime = Date.now();
            const elapsed = ((endTime - startTime) / 1000).toFixed(2);
            addTradingLog(`⚡ 交易确认！用时 ${elapsed}s Hash: ${txHash.slice(0, 10)}...`, 'success');
            
            if (intervalId) {
              clearInterval(intervalId);
            }
            
            resolve(receipt);
            return;
          }
          
          // 检查是否超时
          if (Date.now() - startTime > timeout) {
            if (intervalId) {
              clearInterval(intervalId);
            }
            reject(new Error(`交易超时 (${timeoutSeconds}s)`));
            return;
          }
          
          // 显示等待状态（每2秒显示一次进度）
          const elapsed = ((Date.now() - startTime) / 1000).toFixed(1);
          const elapsedSeconds = Math.floor(elapsed);
          if (elapsedSeconds > 0 && elapsedSeconds % 2 === 0 && elapsed - elapsedSeconds < 0.2) {
            addTradingLog(`⏳ 等待确认... ${elapsed}s (高性能RPC监控频率: ${(1000/txMonitorInterval).toFixed(1)}次/秒)`, 'info');
          }
          
        } catch (error) {
          console.error('检查交易状态失败:', error);
          
          // 检查是否超时
          if (Date.now() - startTime > timeout) {
            if (intervalId) {
              clearInterval(intervalId);
            }
            reject(new Error(`网络错误: ${error.message}`));
          }
        }
      };
      
      // 使用可配置的监控间隔
      intervalId = setInterval(checkStatus, txMonitorInterval);
      
      // 立即执行第一次检查
      checkStatus();
    });
  };

