      const MIN_REQUIRED_BNB = 0.001;
      
      if (parseFloat(ethers.formatEther(walletBnbBalance)) < MIN_REQUIRED_BNB) {
        const rebalanceSuccess = await checkAndAutoRebalanceWallet(wallet, MIN_REQUIRED_BNB);
        if (!rebalanceSuccess) {
          console.log(`无法为钱包 ${wallet.address} 自动转入BNB，卖出交易可能会失败`);
        }
      }
      
      let formattedAmount;
      
