      const gasPriceMultiplier = currentIndex > 1 ? 4n : 3n; // 后续交易使用更高的gas价格
      const adjustedGasPrice = useCustomGas && customGasPrice ? 
        ethers.parseUnits(customGasPrice, 'gwei') : 
        sellGasPrice.gasPrice * gasPriceMultiplier;
      
