// 抽屉宽度
const drawerWidth = 240;

// 样式化的组件
const DrawerHeader = styled('div')(({ theme }) => ({
  display: 'flex',
  alignItems: 'center',
  padding: theme.spacing(0, 1),
  // 必要的占位符，让内容位于AppBar下方
  ...theme.mixins.toolbar,
  justifyContent: 'flex-end',
}));

// 打开状态的抽屉样式
const openedMixin = (theme) => ({
  width: drawerWidth,
  transition: theme.transitions.create('width', {
    easing: theme.transitions.easing.sharp,
    duration: theme.transitions.duration.enteringScreen,
  }),
  overflowX: 'hidden',
});

// 关闭状态的抽屉样式
const closedMixin = (theme) => ({
  transition: theme.transitions.create('width', {
    easing: theme.transitions.easing.sharp,
    duration: theme.transitions.duration.leavingScreen,
  }),
  overflowX: 'hidden',
  width: `calc(${theme.spacing(7)} + 1px)`,
  [theme.breakpoints.up('sm')]: {
    width: `calc(${theme.spacing(8)} + 1px)`,
  },
});

// 主应用组件
const App = () => {
  const theme = useTheme();
  const [currentAppId, setCurrentAppId] = useState('home');
  const [drawerOpen, setDrawerOpen] = useState(false);
  const [walletConnected, setWalletConnected] = useState(false);
  const [walletAddress, setWalletAddress] = useState('0x7db...edf0b');

  // 组件挂载时注入全局样式
  useEffect(() => {
    setupGlobalStyles();
  }, []);

  const handleDrawerOpen = () => {
    setDrawerOpen(true);
  };

  const handleDrawerClose = () => {
    setDrawerOpen(false);
  };

  // 修改菜单项点击处理函数
  const handleMenuItemClick = (appId) => {
    const app = APP_CONFIG.find(app => app.id === appId);
    if (app && app.isExternal && app.link) {
      // 如果是外部链接，在新窗口打开
      window.open(app.link, '_blank');
    } else {
      // 否则切换到对应的组件
      setCurrentAppId(appId);
    }
    setDrawerOpen(false);
  };

  const handleConnectWallet = () => {
    setWalletConnected(true);
  };

  const currentApp = APP_CONFIG.find(app => app.id === currentAppId);

  return (
    <Box sx={{ display: 'flex' }}>
      <CssBaseline />
      <AppBar
        position="fixed"
        sx={{
          zIndex: theme.zIndex.drawer + 1,
          transition: theme.transitions.create(['width', 'margin'], {
            easing: theme.transitions.easing.sharp,
            duration: theme.transitions.duration.leavingScreen,
          }),
          ...(drawerOpen && {
            marginLeft: drawerWidth,
            width: `calc(100% - ${drawerWidth}px)`,
            transition: theme.transitions.create(['width', 'margin'], {
              easing: theme.transitions.easing.sharp,
              duration: theme.transitions.duration.enteringScreen,
            }),
          }),
          backgroundColor: 'white',
          color: 'black',
          boxShadow: '0px 2px 4px -1px rgba(0,0,0,0.05)',
        }}
      >
        <Toolbar>
          <IconButton
            color="inherit"
            aria-label={drawerOpen ? "close drawer" : "open drawer"}
            onClick={drawerOpen ? handleDrawerClose : handleDrawerOpen}
            edge="start"
            sx={{
              marginRight: 2,
              ...(drawerOpen && { display: 'none' }),
            }}
          >
            <MenuIcon />
          </IconButton>
          <Typography
            variant="h6"
            noWrap
            component="div"
            sx={{ flexGrow: 1 }}
          >
            {currentApp ? currentApp.name : 'Home'}
          </Typography>
          <Button
            variant={walletConnected ? "outlined" : "contained"}
            color={walletConnected ? "primary" : "primary"}
            startIcon={<AccountBalanceWalletIcon />}
            onClick={handleConnectWallet}
          >
            {walletConnected ? walletAddress : "连接钱包"}
          </Button>
        </Toolbar>
      </AppBar>
      <Drawer
        variant="permanent"
        open={drawerOpen}
        sx={{
          width: drawerWidth,
          flexShrink: 0,
          whiteSpace: 'nowrap',
          boxSizing: 'border-box',
          ...(drawerOpen ? {
            ...openedMixin(theme),
            '& .MuiDrawer-paper': openedMixin(theme),
          } : {
            ...closedMixin(theme),
            '& .MuiDrawer-paper': closedMixin(theme),
          }),
          '& .MuiDrawer-paper': {
            backgroundColor: '#f8f9fa',
            borderRight: '1px solid #e0e0e0'
          }
        }}
      >
        <Box
          sx={{ 
            display: 'flex', 
            alignItems: 'center', 
            padding: theme.spacing(1, 1),
            ...theme.mixins.toolbar,
            justifyContent: drawerOpen ? 'space-between' : 'center',
            borderBottom: '1px solid #e0e0e0'
          }}
        >
          {drawerOpen ? (
            <>
              <Box sx={{ display: 'flex', alignItems: 'center' }}>
                <img 
                  src={logoImage} 
                  alt="Logo" 
                  style={{ height: 24, marginRight: 8 }} 
                />
                <Typography variant="subtitle1" sx={{ fontWeight: 'bold' }}>
                  Bot Tool
                </Typography>
              </Box>
              <IconButton onClick={handleDrawerClose} size="small">
                <ChevronLeftIcon />
              </IconButton>
            </>
          ) : (
            <img 
              src={logoImage} 
              alt="Logo" 
              style={{ height: 24 }} 
            />
          )}
        </Box>
        <List sx={{ mt: 1 }}>
          {APP_CONFIG.map((app) => (
            <ListItem 
              key={app.id}
              sx={{
                display: 'block',
                mb: 0.5,
                mx: 1,
                px: 1,
                borderRadius: '8px',
                '&.Mui-selected': {
                  backgroundColor: 'rgba(25, 118, 210, 0.08)',
                },
                '&.Mui-selected:hover': {
                  backgroundColor: 'rgba(25, 118, 210, 0.12)',
                },
                '&:hover': {
                  backgroundColor: 'rgba(0, 0, 0, 0.04)',
                }
              }}
              selected={currentAppId === app.id}
              onClick={() => handleMenuItemClick(app.id)}
              component="div"
              disablePadding
            >
              <Box sx={{ 
                display: 'flex', 
                alignItems: 'center', 
                py: 1.5,
                pl: drawerOpen ? 1 : 0,
                justifyContent: drawerOpen ? 'flex-start' : 'center',
                cursor: 'pointer'
              }}>
                <Box sx={{ 
                  color: currentAppId === app.id ? 'primary.main' : 'text.secondary',
                  minWidth: drawerOpen ? 36 : 'auto',
                  display: 'flex',
                  justifyContent: 'center'
                }}>
                  {app.icon}
                </Box>
                {drawerOpen && (
                  <Typography 
                    sx={{ 
                      ml: 2, 
                      fontWeight: currentAppId === app.id ? 'medium' : 'normal',
                      color: currentAppId === app.id ? 'primary.main' : 'text.primary'
                    }}
                  >
                    {app.name}
                  </Typography>
                )}
              </Box>
            </ListItem>
          ))}
        </List>
      </Drawer>
      <Box
        component="main"
        sx={{
          flexGrow: 1,
          p: 0,
          width: '100%',
          minHeight: '100vh',
          backgroundColor: '#f5f5f5',
        }}
      >
        <DrawerHeader />
        {currentApp && !currentApp.isExternal && currentApp.component && 
          React.createElement(currentApp.component)
        }
        {currentAppId === 'home' && <HomeComponent />}
      </Box>
    </Box>
  );
};

const container = document.getElementById('root');
const root = createRoot(container);

root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);
