// 安全级别评估
const evaluatePasswordStrength = (password) => {
  if (!password) return { score: 0, feedback: '请输入密码' };
  
  let score = 0;
  const feedback = [];
  
  // 长度检查
  if (password.length < 8) {
    feedback.push('密码太短，建议至少8个字符');
  } else {
    score += Math.min(2, password.length / 8);
  }
  
  // 复杂度检查
  if (/[A-Z]/.test(password)) score += 1;
  else feedback.push('建议包含大写字母');
  
  if (/[a-z]/.test(password)) score += 1;
  else feedback.push('建议包含小写字母');
  
  if (/[0-9]/.test(password)) score += 1;
  else feedback.push('建议包含数字');
  
  if (/[^A-Za-z0-9]/.test(password)) score += 1;
  else feedback.push('建议包含特殊字符');
  
  // 转换分数到0-5范围
  score = Math.min(5, score);
  
  // 根据分数返回评估结果
  let strength = '非常弱';
  let color = 'error';
  
  if (score >= 4) {
    strength = '非常强';
    color = 'success';
  } else if (score >= 3) {
    strength = '强';
    color = 'success';
  } else if (score >= 2) {
    strength = '中等';
    color = 'warning';
  } else if (score >= 1) {
    strength = '弱';
    color = 'error';
  }
  
  return { 
    score, 
    strength, 
    color, 
    feedback: feedback.join('; ') 
  };
};

// 密钥管理组件
const KeyManager = ({ open, onClose }) => {
  // 状态
  const [currentMasterKey, setCurrentMasterKey] = useState('');
  const [newMasterKey, setNewMasterKey] = useState('');
  const [confirmMasterKey, setConfirmMasterKey] = useState('');
  const [passwordStrength, setPasswordStrength] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [success, setSuccess] = useState(null);
  const [mode, setMode] = useState('view'); // view, change
  
  // 密码强度评估
  useEffect(() => {
    if (newMasterKey) {
      setPasswordStrength(evaluatePasswordStrength(newMasterKey));
    } else {
      setPasswordStrength(null);
    }
  }, [newMasterKey]);
  
  // 验证当前主密钥
  const verifyCurrentMasterKey = () => {
    // 这里需要实现验证逻辑
    // 在实际应用中，这可能涉及到与服务器的通信
    
    // 模拟验证过程
    setLoading(true);
    setTimeout(() => {
      if (currentMasterKey === 'admin' || currentMasterKey === DEFAULT_PASSWORD) {
        setError(null);
        setMode('change');
      } else {
        setError('当前主密钥验证失败');
      }
      setLoading(false);
    }, 1000);
  };
  
  // 更改主密钥
  const changeMasterKey = async () => {
    if (newMasterKey !== confirmMasterKey) {
      setError('新密钥与确认密钥不匹配');
      return;
    }
    
    if (passwordStrength && passwordStrength.score < 3) {
      setError('新密钥安全强度不足，请设置更强的密钥');
      return;
    }
    
    setLoading(true);
    
    try {
      // 这里需要实现密钥更改逻辑
      // 在实际应用中，这可能涉及:
      // 1. 使用旧密钥解密所有加密的私钥
      // 2. 使用新密钥重新加密这些私钥
      // 3. 更新存储的加密主密钥
      
      // 模拟密钥更改过程
      await new Promise(resolve => setTimeout(resolve, 2000));
      
      // 成功后重置状态
      setSuccess('主密钥已成功更新');
      setCurrentMasterKey('');
      setNewMasterKey('');
      setConfirmMasterKey('');
      setMode('view');
      
      // 关闭成功消息
      setTimeout(() => {
        setSuccess(null);
      }, 3000);
    } catch (error) {
      setError(`更新主密钥失败: ${error.message}`);
    } finally {
      setLoading(false);
    }
  };
  
  // 重置表单
  const resetForm = () => {
    setCurrentMasterKey('');
    setNewMasterKey('');
    setConfirmMasterKey('');
    setError(null);
    setSuccess(null);
    setMode('view');
  };
  
  // 关闭对话框
  const handleClose = () => {
    resetForm();
    onClose();
  };
  
  return (
    <Dialog open={open} onClose={handleClose} maxWidth="sm" fullWidth>
      <DialogTitle>
        安全密钥管理
        <IconButton
          aria-label="close"
          onClick={handleClose}
          sx={{
            position: 'absolute',
            right: 8,
            top: 8,
            color: (theme) => theme.palette.grey[500],
          }}
        >
          <CloseIcon />
        </IconButton>
      </DialogTitle>
      
      <DialogContent>
        <Paper sx={{ p: 2, mb: 2 }}>
          <Typography variant="subtitle1" gutterBottom>
            关于密钥安全
          </Typography>
          <Typography variant="body2" paragraph>
            系统使用主密钥来加密和解密您的私钥密码。确保您设置的主密钥足够强大且不会忘记。
            如果您忘记了主密钥，将无法恢复加密的私钥。
          </Typography>
          <Typography variant="body2" sx={{ fontWeight: 'bold', color: 'warning.main' }}>
            请将您的主密钥保存在安全的地方，并且不要与任何人分享。
          </Typography>
        </Paper>
        
        {error && (
          <Alert severity="error" sx={{ mb: 2 }}>
            {error}
          </Alert>
        )}
        
        {mode === 'view' && (
          <Box sx={{ mt: 2 }}>
            <TextField
              label="当前主密钥"
              type="password"
              fullWidth
              value={currentMasterKey}
              onChange={(e) => setCurrentMasterKey(e.target.value)}
              margin="normal"
              autoComplete="new-password"
            />
            <Box sx={{ mt: 2, display: 'flex', justifyContent: 'flex-end' }}>
              <Button
                variant="contained"
                color="primary"
                onClick={verifyCurrentMasterKey}
                disabled={loading || !currentMasterKey}
              >
                {loading ? <CircularProgress size={24} /> : '验证并继续'}
              </Button>
            </Box>
          </Box>
        )}
        
        {mode === 'change' && (
          <Box sx={{ mt: 2 }}>
            <TextField
              label="新主密钥"
              type="password"
              fullWidth
              value={newMasterKey}
              onChange={(e) => setNewMasterKey(e.target.value)}
              margin="normal"
              autoComplete="new-password"
            />
            
            {passwordStrength && (
              <Box sx={{ mt: 1, mb: 2 }}>
                <Typography variant="body2" sx={{ color: passwordStrength.color + '.main' }}>
                  密码强度: {passwordStrength.strength}
                </Typography>
                {passwordStrength.feedback && (
                  <Typography variant="caption" color="text.secondary">
                    {passwordStrength.feedback}
                  </Typography>
                )}
              </Box>
            )}
            
            <TextField
              label="确认新主密钥"
              type="password"
              fullWidth
              value={confirmMasterKey}
              onChange={(e) => setConfirmMasterKey(e.target.value)}
              margin="normal"
              autoComplete="new-password"
            />
            
            <Box sx={{ mt: 2, display: 'flex', justifyContent: 'space-between' }}>
              <Button
                variant="outlined"
                onClick={() => setMode('view')}
                disabled={loading}
              >
                返回
              </Button>
              <Button
                variant="contained"
                color="primary"
                onClick={changeMasterKey}
                disabled={loading || !newMasterKey || !confirmMasterKey}
              >
                {loading ? <CircularProgress size={24} /> : '更新主密钥'}
              </Button>
            </Box>
          </Box>
        )}
      </DialogContent>
      
      <Snackbar
        open={!!success}
        autoHideDuration={6000}
        onClose={() => setSuccess(null)}
        message={success}
        action={
          <IconButton
            size="small"
            aria-label="close"
            color="inherit"
            onClick={() => setSuccess(null)}
          >
            <CloseIcon fontSize="small" />
          </IconButton>
        }
      />
    </Dialog>
  );
};

export default KeyManager; 