import React, { useState, useEffect, useRef } from 'react';
import { 
  Container, Paper, Typography, TextField, Button, Box, 
  Grid, Alert, CircularProgress, IconButton, Divider,
  Dialog, DialogTitle, DialogContent, DialogActions,
  Chip, FormControlLabel, Switch, InputAdornment, Tooltip,
  Snackbar, Collapse, Tab, Tabs, Card, CardContent,
  Table, TableHead, TableBody, TableRow, TableCell
} from '@mui/material';
import ContentCopyIcon from '@mui/icons-material/ContentCopy';
import VisibilityIcon from '@mui/icons-material/Visibility';
import VisibilityOffIcon from '@mui/icons-material/VisibilityOff';
import LockIcon from '@mui/icons-material/Lock';
import KeyIcon from '@mui/icons-material/Key';
import SecurityIcon from '@mui/icons-material/Security';
import { 
  encryptPrivateKey, 
  decryptPrivateKey, 
  maskPrivateKey, 
  DEFAULT_PASSWORD,
  processImportedKeys,
  processPrivateKey,
  isValidPrivateKey
} from './crypto-utils';

// 评估密码强度
const evaluatePasswordStrength = (password) => {
  if (!password) return { score: 0, feedback: '请输入密码' };
  
  let score = 0;
  const feedback = [];
  
  // 长度检查
  if (password.length < 8) {
    feedback.push('密码太短，建议至少8个字符');
  } else {
    score += Math.min(2, password.length / 8);
  }
  
  // 复杂度检查
  if (/[A-Z]/.test(password)) score += 1;
  else feedback.push('建议包含大写字母');
  
  if (/[a-z]/.test(password)) score += 1;
  else feedback.push('建议包含小写字母');
  
  if (/[0-9]/.test(password)) score += 1;
  else feedback.push('建议包含数字');
  
  if (/[^A-Za-z0-9]/.test(password)) score += 1;
  else feedback.push('建议包含特殊字符');
  
  // 分数评估
  let strengthText = '';
  let color = '';
  
  if (score < 2) {
    strengthText = '弱';
    color = 'error';
  } else if (score < 4) {
    strengthText = '中等';
    color = 'warning';
  } else {
    strengthText = '强';
    color = 'success';
  }
  
  return { 
    score, 
    feedback: feedback.join('，'), 
    strengthText, 
    color 
  };
};

const KeyEncryptor = () => {
  // 状态变量
  const [privateKey, setPrivateKey] = useState('');
  const [password, setPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [customPassword, setCustomPassword] = useState(false);
  const [encryptedKey, setEncryptedKey] = useState('');
  const [decryptedKey, setDecryptedKey] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [showDecryptedKey, setShowDecryptedKey] = useState(false);
  const [tabValue, setTabValue] = useState(0);
  const [passwordStrength, setPasswordStrength] = useState({ score: 0, feedback: '', strengthText: '', color: 'error' });
  const [batchResults, setBatchResults] = useState([]);
  
  // 复制到剪贴板
  const copyToClipboard = (text) => {
    navigator.clipboard.writeText(text)
      .then(() => {
        setSuccess('已复制到剪贴板');
        setTimeout(() => setSuccess(''), 3000);
      })
      .catch(err => {
        setError('复制失败: ' + err.message);
      });
  };
  
  // 加密私钥
  const encryptKey = () => {
    setLoading(true);
    setError('');
    setSuccess('');
    setEncryptedKey('');
    
    try {
      // 验证私钥
      if (!privateKey.trim()) {
        throw new Error('请输入私钥');
      }
      
      // 处理私钥格式
      const processedKey = processPrivateKey(privateKey.trim());
      
      if (!isValidPrivateKey(processedKey)) {
        throw new Error('私钥格式不正确');
      }
      
      // 验证密码
      if (customPassword) {
        if (!password) {
          throw new Error('请输入密码');
        }
        
        if (password !== confirmPassword) {
          throw new Error('两次密码输入不一致');
        }
        
        if (passwordStrength.score < 2) {
          throw new Error('密码强度太弱，请使用更复杂的密码');
        }
      }
      
      // 使用用户密码或默认密码
      const actualPassword = customPassword ? password : DEFAULT_PASSWORD;
      
      // 加密私钥
      const encrypted = encryptPrivateKey(processedKey, actualPassword);
      setEncryptedKey(encrypted);
      setSuccess('私钥加密成功！' + (customPassword ? '请妥善保管您的密码，丢失将无法恢复私钥。' : ''));
    } catch (err) {
      setError(err.message || '加密失败');
    } finally {
      setLoading(false);
    }
  };
  
  // 解密私钥
  const decryptKey = () => {
    setLoading(true);
    setError('');
    setSuccess('');
    setDecryptedKey('');
    
    try {
      // 验证加密密文
      if (!encryptedKey.trim()) {
        throw new Error('请输入加密后的私钥');
      }
      
      // 验证密码
      if (customPassword && !password) {
        throw new Error('请输入密码');
      }
      
      // 使用用户密码或默认密码
      const actualPassword = customPassword ? password : DEFAULT_PASSWORD;
      
      // 解密私钥
      const decrypted = decryptPrivateKey(encryptedKey.trim(), actualPassword);
      
      if (!isValidPrivateKey(decrypted)) {
        throw new Error('解密失败，密码可能不正确');
      }
      
      setDecryptedKey(decrypted);
      setSuccess('私钥解密成功！');
    } catch (err) {
      setError(err.message || '解密失败');
    } finally {
      setLoading(false);
    }
  };
  
  // 批量加密私钥
  const batchEncryptKeys = () => {
    setLoading(true);
    setError('');
    setSuccess('');
    setBatchResults([]);
    
    try {
      // 验证私钥
      if (!privateKey.trim()) {
        throw new Error('请输入私钥');
      }
      
      // 处理私钥格式
      const processedKeys = privateKey.trim().split('\n').map(key => processPrivateKey(key.trim()));
      
      if (!processedKeys.every(isValidPrivateKey)) {
        throw new Error('私钥格式不正确');
      }
      
      // 验证密码
      if (customPassword) {
        if (!password) {
          throw new Error('请输入密码');
        }
        
        if (password !== confirmPassword) {
          throw new Error('两次密码输入不一致');
        }
        
        if (passwordStrength.score < 2) {
          throw new Error('密码强度太弱，请使用更复杂的密码');
        }
      }
      
      // 使用用户密码或默认密码
      const actualPassword = customPassword ? password : DEFAULT_PASSWORD;
      
      // 批量加密私钥
      const results = processedKeys.map(key => {
        try {
          const encrypted = encryptPrivateKey(key, actualPassword);
          return {
            originalKey: key,
            encryptedKey: encrypted,
            success: true
          };
        } catch (err) {
          return {
            originalKey: key,
            encryptedKey: '',
            success: false
          };
        }
      });
      
      setBatchResults(results);
      setSuccess('批量加密成功！');
    } catch (err) {
      setError(err.message || '批量加密失败');
    } finally {
      setLoading(false);
    }
  };
  
  // 清除所有数据
  const clearAll = () => {
    setPrivateKey('');
    setPassword('');
    setConfirmPassword('');
    setEncryptedKey('');
    setDecryptedKey('');
    setError('');
    setSuccess('');
    setBatchResults([]);
  };
  
  // 密码变化时评估强度
  useEffect(() => {
    if (customPassword) {
      const strength = evaluatePasswordStrength(password);
      setPasswordStrength(strength);
    }
  }, [password, customPassword]);
  
  // 标签页切换
  const handleTabChange = (event, newValue) => {
    setTabValue(newValue);
    clearAll();
  };
  
  // 导出批量处理结果为CSV
  const exportBatchResults = () => {
    try {
      // 准备CSV内容
      let csvContent = "原始私钥,加密后的私钥,状态\n";
      
      batchResults.forEach(result => {
        // 修改: 不管成功与否，都包含原始私钥和加密私钥
        csvContent += `"${result.originalKey}","${result.encryptedKey}","${result.success ? '成功' : '失败'}"\n`;
      });
      
      // 创建Blob对象
      const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
      const url = URL.createObjectURL(blob);
      
      // 创建下载链接
      const link = document.createElement("a");
      const timestamp = new Date().toISOString().replace(/[:.]/g, '-');
      link.setAttribute("href", url);
      link.setAttribute("download", `encrypted-keys-${timestamp}.csv`);
      link.style.visibility = 'hidden';
      
      // 添加到DOM、触发下载并清理
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      
      setSuccess('CSV文件导出成功！');
    } catch (err) {
      setError('导出CSV失败: ' + err.message);
    }
  };
  
  return (
    <Container maxWidth="md" sx={{ mt: 4, mb: 4 }}>
      <Paper sx={{ p: 3, borderRadius: 2, boxShadow: 3 }}>
        <Box sx={{ mb: 3, display: 'flex', alignItems: 'center' }}>
          <SecurityIcon sx={{ mr: 1, color: 'primary.main' }} />
          <Typography variant="h5" component="h1" gutterBottom>
            私钥加密工具
          </Typography>
        </Box>
        
        <Typography variant="body2" color="text.secondary" paragraph>
          此工具可以对以太坊私钥进行加密，加密后的私钥可以更安全地存储和分享。加密使用对称加密算法，只有知道密码的人才能解密。
        </Typography>
        
        <Box sx={{ borderBottom: 1, borderColor: 'divider', mb: 2 }}>
          <Tabs value={tabValue} onChange={handleTabChange} aria-label="加密解密选项卡">
            <Tab label="加密私钥" id="tab-0" />
            <Tab label="解密私钥" id="tab-1" />
            <Tab label="批量处理" id="tab-2" />
          </Tabs>
        </Box>
        
        {/* 加密私钥标签页 */}
        {tabValue === 0 && (
          <Box sx={{ mt: 2 }}>
            <TextField
              label="私钥"
              fullWidth
              multiline
              rows={2}
              variant="outlined"
              value={privateKey}
              onChange={(e) => setPrivateKey(e.target.value)}
              placeholder="输入以太坊私钥，格式为64位十六进制字符（可以带0x前缀）"
              margin="normal"
              type={showPassword ? "text" : "password"}
              InputProps={{
                endAdornment: (
                  <InputAdornment position="end">
                    <IconButton
                      onClick={() => setShowPassword(!showPassword)}
                      edge="end"
                    >
                      {showPassword ? <VisibilityOffIcon /> : <VisibilityIcon />}
                    </IconButton>
                  </InputAdornment>
                ),
              }}
            />
            
            <FormControlLabel
              control={
                <Switch
                  checked={customPassword}
                  onChange={(e) => setCustomPassword(e.target.checked)}
                />
              }
              label="使用自定义密码"
            />
            
            {customPassword && (
              <>
                <TextField
                  label="密码"
                  fullWidth
                  variant="outlined"
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  type={showPassword ? "text" : "password"}
                  margin="normal"
                  InputProps={{
                    endAdornment: (
                      <InputAdornment position="end">
                        <Chip 
                          label={passwordStrength.strengthText} 
                          color={passwordStrength.color} 
                          size="small" 
                          variant="outlined"
                        />
                      </InputAdornment>
                    ),
                  }}
                />
                
                {passwordStrength.feedback && (
                  <Typography variant="caption" color="text.secondary">
                    {passwordStrength.feedback}
                  </Typography>
                )}
                
                <TextField
                  label="确认密码"
                  fullWidth
                  variant="outlined"
                  value={confirmPassword}
                  onChange={(e) => setConfirmPassword(e.target.value)}
                  type={showPassword ? "text" : "password"}
                  margin="normal"
                  error={password !== confirmPassword && confirmPassword !== ''}
                  helperText={
                    password !== confirmPassword && confirmPassword !== '' 
                      ? '密码不匹配' 
                      : ''
                  }
                />
              </>
            )}
            
            <Box sx={{ mt: 2, mb: 2 }}>
              <Button
                variant="contained"
                color="primary"
                onClick={encryptKey}
                disabled={loading}
                startIcon={<LockIcon />}
                sx={{ mr: 1 }}
              >
                {loading ? <CircularProgress size={24} /> : '加密私钥'}
              </Button>
              
              <Button
                variant="outlined"
                onClick={clearAll}
                disabled={loading}
              >
                清除
              </Button>
            </Box>
            
            {encryptedKey && (
              <Card variant="outlined" sx={{ mt: 2 }}>
                <CardContent>
                  <Typography variant="subtitle1" gutterBottom>
                    加密结果:
                  </Typography>
                  
                  <TextField
                    fullWidth
                    multiline
                    rows={4}
                    variant="outlined"
                    value={encryptedKey}
                    InputProps={{
                      readOnly: true,
                      endAdornment: (
                        <InputAdornment position="end">
                          <IconButton
                            onClick={() => copyToClipboard(encryptedKey)}
                            edge="end"
                            title="复制到剪贴板"
                          >
                            <ContentCopyIcon />
                          </IconButton>
                        </InputAdornment>
                      ),
                    }}
                  />
                  
                  <Typography variant="caption" color="text.secondary" sx={{ mt: 1, display: 'block' }}>
                    此加密字符串可以安全地存储或分享。
                    {customPassword ? '解密时需要提供您设置的自定义密码。' : '解密时将使用系统默认密码。'}
                  </Typography>
                </CardContent>
              </Card>
            )}
          </Box>
        )}
        
        {/* 解密私钥标签页 */}
        {tabValue === 1 && (
          <Box sx={{ mt: 2 }}>
            <TextField
              label="加密的私钥"
              fullWidth
              multiline
              rows={4}
              variant="outlined"
              value={encryptedKey}
              onChange={(e) => setEncryptedKey(e.target.value)}
              placeholder="输入加密后的私钥字符串"
              margin="normal"
            />
            
            <FormControlLabel
              control={
                <Switch
                  checked={customPassword}
                  onChange={(e) => setCustomPassword(e.target.checked)}
                />
              }
              label="使用自定义密码"
            />
            
            {customPassword && (
              <TextField
                label="密码"
                fullWidth
                variant="outlined"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                type={showPassword ? "text" : "password"}
                margin="normal"
                InputProps={{
                  endAdornment: (
                    <InputAdornment position="end">
                      <IconButton
                        onClick={() => setShowPassword(!showPassword)}
                        edge="end"
                      >
                        {showPassword ? <VisibilityOffIcon /> : <VisibilityIcon />}
                      </IconButton>
                    </InputAdornment>
                  ),
                }}
              />
            )}
            
            <Box sx={{ mt: 2, mb: 2 }}>
              <Button
                variant="contained"
                color="primary"
                onClick={decryptKey}
                disabled={loading}
                startIcon={<KeyIcon />}
                sx={{ mr: 1 }}
              >
                {loading ? <CircularProgress size={24} /> : '解密私钥'}
              </Button>
              
              <Button
                variant="outlined"
                onClick={clearAll}
                disabled={loading}
              >
                清除
              </Button>
            </Box>
            
            {decryptedKey && (
              <Card variant="outlined" sx={{ mt: 2 }}>
                <CardContent>
                  <Typography variant="subtitle1" gutterBottom>
                    解密结果:
                  </Typography>
                  
                  <TextField
                    fullWidth
                    variant="outlined"
                    value={showDecryptedKey ? decryptedKey : maskPrivateKey(decryptedKey)}
                    InputProps={{
                      readOnly: true,
                      endAdornment: (
                        <InputAdornment position="end">
                          <IconButton
                            onClick={() => setShowDecryptedKey(!showDecryptedKey)}
                            edge="end"
                            title={showDecryptedKey ? "隐藏私钥" : "显示私钥"}
                            sx={{ mr: 1 }}
                          >
                            {showDecryptedKey ? <VisibilityOffIcon /> : <VisibilityIcon />}
                          </IconButton>
                          <IconButton
                            onClick={() => copyToClipboard(decryptedKey)}
                            edge="end"
                            title="复制到剪贴板"
                          >
                            <ContentCopyIcon />
                          </IconButton>
                        </InputAdornment>
                      ),
                    }}
                  />
                  
                  <Typography variant="caption" color="error" sx={{ mt: 1, display: 'block' }}>
                    警告：请不要将私钥分享给任何人！拥有私钥的人可以控制该钱包中的所有资产。
                  </Typography>
                </CardContent>
              </Card>
            )}
          </Box>
        )}
        
        {/* 批量处理标签页 */}
        {tabValue === 2 && (
          <Box sx={{ mt: 2 }}>
            <Typography variant="body2" color="text.secondary" paragraph>
              批量加密多个私钥，每行输入一个私钥。也可以直接粘贴CSV文件中的私钥列。
            </Typography>
            
            <TextField
              label="多个私钥（每行一个）"
              fullWidth
              multiline
              rows={6}
              variant="outlined"
              value={privateKey}
              onChange={(e) => setPrivateKey(e.target.value)}
              placeholder="输入多个私钥，每行一个。支持CSV文件中的私钥列。"
              margin="normal"
              type={showPassword ? "text" : "password"}
              InputProps={{
                endAdornment: (
                  <InputAdornment position="end">
                    <IconButton
                      onClick={() => setShowPassword(!showPassword)}
                      edge="end"
                    >
                      {showPassword ? <VisibilityOffIcon /> : <VisibilityIcon />}
                    </IconButton>
                  </InputAdornment>
                ),
              }}
            />
            
            <FormControlLabel
              control={
                <Switch
                  checked={customPassword}
                  onChange={(e) => setCustomPassword(e.target.checked)}
                />
              }
              label="使用自定义密码"
            />
            
            {customPassword && (
              <>
                <TextField
                  label="密码"
                  fullWidth
                  variant="outlined"
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  type={showPassword ? "text" : "password"}
                  margin="normal"
                  InputProps={{
                    endAdornment: (
                      <InputAdornment position="end">
                        <Chip 
                          label={passwordStrength.strengthText} 
                          color={passwordStrength.color} 
                          size="small" 
                          variant="outlined"
                        />
                      </InputAdornment>
                    ),
                  }}
                />
                
                {passwordStrength.feedback && (
                  <Typography variant="caption" color="text.secondary">
                    {passwordStrength.feedback}
                  </Typography>
                )}
                
                <TextField
                  label="确认密码"
                  fullWidth
                  variant="outlined"
                  value={confirmPassword}
                  onChange={(e) => setConfirmPassword(e.target.value)}
                  type={showPassword ? "text" : "password"}
                  margin="normal"
                  error={password !== confirmPassword && confirmPassword !== ''}
                  helperText={
                    password !== confirmPassword && confirmPassword !== '' 
                      ? '密码不匹配' 
                      : ''
                  }
                />
              </>
            )}
            
            <Box sx={{ mt: 2, mb: 2 }}>
              <Button
                variant="contained"
                color="primary"
                onClick={batchEncryptKeys}
                disabled={loading}
                startIcon={<LockIcon />}
                sx={{ mr: 1 }}
              >
                {loading ? <CircularProgress size={24} /> : '批量加密'}
              </Button>
              
              <Button
                variant="outlined"
                onClick={clearAll}
                disabled={loading}
              >
                清除
              </Button>
            </Box>
            
            {batchResults.length > 0 && (
              <Card variant="outlined" sx={{ mt: 2 }}>
                <CardContent>
                  <Typography variant="subtitle1" gutterBottom>
                    批量加密结果:
                  </Typography>
                  
                  <Box sx={{ mt: 2, maxHeight: '300px', overflow: 'auto' }}>
                    <Table size="small">
                      <TableHead>
                        <TableRow>
                          <TableCell>原始私钥（已隐藏）</TableCell>
                          <TableCell>加密后的私钥</TableCell>
                          <TableCell>状态</TableCell>
                          <TableCell>操作</TableCell>
                        </TableRow>
                      </TableHead>
                      <TableBody>
                        {batchResults.map((result, index) => (
                          <TableRow key={index}>
                            <TableCell>{maskPrivateKey(result.originalKey)}</TableCell>
                            <TableCell 
                              sx={{ 
                                maxWidth: '280px', 
                                overflow: 'hidden', 
                                textOverflow: 'ellipsis',
                                whiteSpace: 'nowrap' 
                              }}
                            >
                              {result.encryptedKey}
                            </TableCell>
                            <TableCell>
                              <Chip 
                                label={result.success ? '成功' : '失败'} 
                                color={result.success ? 'success' : 'error'} 
                                size="small" 
                              />
                            </TableCell>
                            <TableCell>
                              <IconButton 
                                size="small" 
                                onClick={() => copyToClipboard(result.encryptedKey)}
                                disabled={!result.success}
                              >
                                <ContentCopyIcon fontSize="small" />
                              </IconButton>
                            </TableCell>
                          </TableRow>
                        ))}
                      </TableBody>
                    </Table>
                  </Box>
                  
                  <Box sx={{ mt: 2, display: 'flex', justifyContent: 'space-between' }}>
                    <Button 
                      variant="outlined" 
                      onClick={exportBatchResults}
                      disabled={batchResults.length === 0}
                    >
                      导出CSV
                    </Button>
                    <Typography variant="body2" color="text.secondary">
                      共处理 {batchResults.length} 个私钥，成功 {batchResults.filter(r => r.success).length} 个
                    </Typography>
                  </Box>
                </CardContent>
              </Card>
            )}
          </Box>
        )}
        
        {/* 错误和成功提示 */}
        {error && (
          <Alert severity="error" sx={{ mt: 2 }}>
            {error}
          </Alert>
        )}
        
        {success && (
          <Alert severity="success" sx={{ mt: 2 }}>
            {success}
          </Alert>
        )}
        
        <Divider sx={{ my: 3 }} />
        
        <Typography variant="body2" color="text.secondary">
          安全提示：
        </Typography>
        <Box component="div" sx={{ mt: 1, ml: 2 }}>
          <ul>
            <li>私钥加密后仍然需要妥善保管，不要上传到不安全的网站或服务</li>
            <li>使用自定义密码时，请确保密码足够复杂且不要忘记，否则将无法恢复私钥</li>
            <li>为提高安全性，建议不要在联网的设备上直接输入或显示私钥</li>
          </ul>
        </Box>
      </Paper>
      
      {/* 复制成功提示 */}
      <Snackbar
        open={!!success}
        autoHideDuration={3000}
        onClose={() => setSuccess('')}
        message={success}
      />
    </Container>
  );
};

export default KeyEncryptor; 