// 创建一个全局消息状态管理
let messageQueue = [];
let isProcessingMessage = false;

const processMessageQueue = () => {
  if (isProcessingMessage || messageQueue.length === 0) return;
  
  isProcessingMessage = true;
  const { content, type } = messageQueue[0];
  
  const existingMessage = document.querySelector('.global-message');
  if (existingMessage) {
    document.body.removeChild(existingMessage);
  }
  
  const messageElement = document.createElement('div');
  messageElement.className = 'global-message';
  messageElement.textContent = content;
  messageElement.style.cssText = `
    position: fixed;
    top: 20px;
    left: 50%;
    transform: translateX(-50%);
    padding: 10px 20px;
    border-radius: 4px;
    z-index: 1000;
    box-shadow: 0 3px 6px rgba(0,0,0,0.2);
    color: #fff;
    background-color: ${
      type === 'success' ? '#52c41a' :
      type === 'error' ? '#ff4d4f' :
      type === 'warning' ? '#faad14' :
      '#1890ff'
    };
  `;
  
  document.body.appendChild(messageElement);
  
  setTimeout(() => {
    messageElement.style.opacity = '0';
    messageElement.style.transition = 'opacity 0.3s';
    
    setTimeout(() => {
      if (messageElement.parentNode === document.body) {
      document.body.removeChild(messageElement);
      }
      messageQueue.shift();
      isProcessingMessage = false;
      processMessageQueue();
    }, 300);
  }, 3000);
};

// 创建消息通知函数
const showMessage = (content, type = 'info') => {
  messageQueue.push({ content, type });
  processMessageQueue();
};

// 创建自定义消息对象
const message = {
  success: (content) => showMessage(content, 'success'),
  error: (content) => showMessage(content, 'error'),
  warning: (content) => showMessage(content, 'warning'),
  info: (content) => showMessage(content, 'info')
};

