// ==================== 工具函数 ====================
function formatBigInt(value, decimals = 18) {
  try {
    if (!value || value === 0n) {
      console.log('formatBigInt: 输入值为0或null');
      return '0';
    }
    
    console.log(`formatBigInt: 输入值=${value.toString()}, 精度=${decimals}`);
    
    const formatted = ethers.formatUnits(value, decimals);
    console.log(`formatBigInt: ethers.formatUnits结果=${formatted}`);
    
    const num = parseFloat(formatted);
    console.log(`formatBigInt: parseFloat结果=${num}`);
    
    // 如果是0，直接返回'0'
    if (num === 0) {
      console.log('formatBigInt: 数值为0');
      return '0';
    }
    
    // 如果是整数，不显示小数点
    if (num === Math.floor(num)) {
      const result = num.toString();
      console.log(`formatBigInt: 整数结果=${result}`);
      return result;
    }
    
    let result;
    // 根据数值大小决定小数位数
    if (num >= 1000000) {
      result = num.toFixed(0); // 大数不显示小数
    } else if (num >= 1000) {
      result = num.toFixed(2); // 千位显示2位小数
    } else if (num >= 1) {
      result = num.toFixed(4); // 个位显示4位小数
    } else if (num >= 0.0001) {
      result = num.toFixed(6); // 小数显示6位
    } else if (num >= 0.00000001) {
      result = num.toFixed(8); // 很小的数显示8位
    } else {
      // 对于极小的数，使用科学计数法或显示更多位数
      if (num < 1e-15) {
        result = num.toExponential(4); // 科学计数法
      } else {
        // 显示足够的位数以避免显示为0
        result = num.toFixed(18).replace(/\.?0+$/, ''); // 移除尾随的0
      }
    }
    
    console.log(`formatBigInt: 最终结果=${result}`);
    return result;
  } catch (error) {
    console.error('格式化BigInt失败:', error);
    return '0';
  }
}

function getRandomAmount(min, max, decimals = 6) {
  return (Math.random() * (max - min) + min).toFixed(decimals);
}

function formatPrice(price) {
  if (price === null || price === undefined || isNaN(price)) {
    return '0';
  }
  const numPrice = Number(price);
  if (numPrice < 0.000001) return numPrice.toExponential(4);
  if (numPrice < 0.001) return numPrice.toFixed(8);
  if (numPrice < 1) return numPrice.toFixed(6);
  if (numPrice < 1000) return numPrice.toFixed(4);
  return numPrice.toFixed(2);
}

function formatBalance(balance) {
  try {
    if (!balance || balance === '0') return '0';
    
    const num = parseFloat(balance);
    
    // 如果是0，直接返回'0'
    if (num === 0) return '0';
    
    // 如果是整数，不显示小数点
    if (num === Math.floor(num)) {
      return num.toString();
    }
    
    // 根据数值大小决定小数位数
    if (num >= 1000000) {
      return num.toFixed(0); // 大数不显示小数
    } else if (num >= 1000) {
      return num.toFixed(2); // 千位显示2位小数
    } else if (num >= 1) {
      return num.toFixed(4); // 个位显示4位小数
    } else if (num >= 0.0001) {
      return num.toFixed(6); // 小数显示6位
    } else {
      return num.toFixed(8); // 很小的数显示8位
    }
  } catch (error) {
    console.error('格式化余额失败:', error);
    return '0';
  }
}

async function getBNBBalance(provider, address) {
  try {
    const balance = await provider.getBalance(address);
    return ethers.formatEther(balance);
  } catch (error) {
    console.error("获取BNB余额失败:", error);
    return "0";
  }
}

async function getUSD1Balance(provider, walletAddress) {
  try {
    const tokenContract = new ethers.Contract(DEFAULT_TOKENS.USD1.address, ERC20_ABI, provider);
    const balance = await tokenContract.balanceOf(walletAddress);
    return ethers.formatUnits(balance, DEFAULT_TOKENS.USD1.decimals);
  } catch (error) {
    console.error("获取USD1余额失败:", error);
    return "0";
  }
}

