// 创建一个简单的消息通知函数
const showMessage = (content, type = 'info', duration = 3000) => {
  const messageElement = document.createElement('div');
  messageElement.textContent = content;
  messageElement.style.position = 'fixed';
  messageElement.style.top = '20px';
  messageElement.style.left = '50%';
  messageElement.style.transform = 'translateX(-50%)';
  messageElement.style.padding = '10px 20px';
  messageElement.style.borderRadius = '4px';
  messageElement.style.zIndex = '1000';
  messageElement.style.boxShadow = '0 3px 6px rgba(0,0,0,0.2)';
  
  if (type === 'success') {
    messageElement.style.backgroundColor = '#52c41a';
    messageElement.style.color = '#fff';
  } else if (type === 'error') {
    messageElement.style.backgroundColor = '#ff4d4f';
    messageElement.style.color = '#fff';
  } else if (type === 'warning') {
    messageElement.style.backgroundColor = '#faad14';
    messageElement.style.color = '#fff';
  } else {
    messageElement.style.backgroundColor = '#1890ff';
    messageElement.style.color = '#fff';
  }
  
  document.body.appendChild(messageElement);
  
  setTimeout(() => {
    messageElement.style.opacity = '0';
    messageElement.style.transition = 'opacity 0.3s';
    setTimeout(() => {
      document.body.removeChild(messageElement);
    }, 300);
  }, duration);
};

// 创建自定义消息对象
const message = {
  success: (content, duration) => showMessage(content, 'success', duration),
  error: (content, duration) => showMessage(content, 'error', duration),
  warning: (content, duration) => showMessage(content, 'warning', duration),
  info: (content, duration) => showMessage(content, 'info', duration)
};

// ==================== RPC重试机制 ====================
let currentRpcIndex = 0;
let lastRequestTime = 0;
const MIN_REQUEST_INTERVAL = 100; // 最小请求间隔100ms

// 增强的RPC重试机制 - 优化批量交易
const withRetry = async (operation, maxRetries = 3, delay = 1000) => {
  for (let i = 0; i < maxRetries; i++) {
    try {
      // 添加请求间隔控制
      const now = Date.now();
      const timeSinceLastRequest = now - lastRequestTime;
      if (timeSinceLastRequest < MIN_REQUEST_INTERVAL) {
        await new Promise(resolve => setTimeout(resolve, MIN_REQUEST_INTERVAL - timeSinceLastRequest));
      }
      lastRequestTime = Date.now();
      
      const result = await operation();
      return result;
    } catch (error) {
      console.log(`RPC请求失败 (尝试 ${i + 1}/${maxRetries}):`, error.message);
      
      // 如果是速率限制错误，切换RPC节点
      if (error.message.includes('rate limit') || 
          error.message.includes('BAD_DATA') || 
          error.code === 'BAD_DATA' ||
          error.message.includes('too many requests')) {
        console.log('检测到速率限制，切换RPC节点...');
        currentRpcIndex = (currentRpcIndex + 1) % RPC_URLS.length;
        const newRpcUrl = RPC_URLS[currentRpcIndex];
        console.log(`切换到RPC节点: ${newRpcUrl.url || newRpcUrl}`);
      }
      
      if (i === maxRetries - 1) {
        throw error;
      }
      
      // 智能退避延迟 - 根据错误类型调整
      let waitTime = delay * Math.pow(2, i);
      
      // 针对不同错误类型的特殊处理
      if (error.message.includes('nonce too low') || error.message.includes('nonce')) {
        // nonce错误需要更长的等待时间
        waitTime *= 3;
      } else if (error.message.includes('insufficient funds') || error.message.includes('balance')) {
        // 余额不足错误，快速失败
        throw error;
      } else if (error.message.includes('network') || error.message.includes('timeout')) {
        // 网络错误，增加等待时间
        waitTime *= 2;
      } else if (error.message.includes('reverted') || error.message.includes('execution reverted')) {
        // 交易回滚，可能是滑点问题，快速重试
        waitTime = Math.min(waitTime, 1000);
      }
      
      // 添加随机抖动避免雷群效应
      const jitter = Math.random() * 500;
      const finalWaitTime = waitTime + jitter;
      
      console.log(`等待 ${Math.round(finalWaitTime)}ms 后重试...`);
      await new Promise(resolve => setTimeout(resolve, finalWaitTime));
    }
  }
};

// 创建带重试的RPC提供者
