// 批量交易队列管理器 - 优化20个钱包同时交易
class BatchTransactionManager {
  constructor(maxConcurrent = 5, batchDelay = 1000) {
    this.maxConcurrent = maxConcurrent;
    this.batchDelay = batchDelay;
    this.activeTransactions = 0;
    this.queue = [];
    this.results = [];
  }

  // 添加交易到队列
  async addTransaction(transactionFn, wallet, params) {
    return new Promise((resolve, reject) => {
      this.queue.push({
        transactionFn,
        wallet,
        params,
        resolve,
        reject,
        timestamp: Date.now()
      });
      this.processQueue();
    });
  }

  // 处理队列
  async processQueue() {
    while (this.queue.length > 0 && this.activeTransactions < this.maxConcurrent) {
      const transaction = this.queue.shift();
      this.activeTransactions++;
      
      this.executeTransaction(transaction)
        .finally(() => {
          this.activeTransactions--;
          this.processQueue(); // 继续处理队列
        });
    }
  }

  // 执行单个交易
  async executeTransaction(transaction) {
    const { transactionFn, wallet, params, resolve, reject } = transaction;
    
    try {
      // 添加微小的随机延迟避免冲突
      const jitter = Math.random() * 200;
      await new Promise(r => setTimeout(r, jitter));
      
      const result = await transactionFn(wallet, ...params);
      this.results.push({ wallet: wallet.address, success: true, result });
      resolve(result);
    } catch (error) {
      this.results.push({ wallet: wallet.address, success: false, error: error.message });
      reject(error);
    }
  }

  // 获取统计信息
  getStats() {
    const total = this.results.length;
    const successful = this.results.filter(r => r.success).length;
    const failed = total - successful;
    const successRate = total > 0 ? ((successful / total) * 100).toFixed(1) : '0';
    
    return {
      total,
      successful,
      failed,
      successRate,
      results: this.results
    };
  }

  // 重置管理器
  reset() {
    this.queue = [];
    this.results = [];
    this.activeTransactions = 0;
  }
}

