// 提供一个简单的方法用于在前端计算代币的USDT价值
export const calculateUSDTValueFromFIST = (tokenAmount, tokenPrice, fistUsdtRate) => {
  if (!tokenAmount || isNaN(tokenAmount) || tokenAmount <= 0) {
    return 0;
  }
  
  if (!tokenPrice || isNaN(tokenPrice) || tokenPrice <= 0) {
    return 0;
  }
  
  if (!fistUsdtRate || isNaN(fistUsdtRate) || fistUsdtRate <= 0) {
    return 0;
  }
  
  // 1. 计算代币的FIST价值
  const fistValue = tokenAmount * tokenPrice;
  
  // 2. 计算USDT价值
  return fistValue * fistUsdtRate;
};

