// ==================== 工具函数 ====================
function formatBigInt(value, decimals = 18) {
  if (!value || value.toString() === '0') return '0';
  try {
    return ethers.formatUnits(value, decimals);
  } catch (err) {
    console.error("格式化BigInt失败:", err);
    return '0';
  }
}

function getRandomAmount(min, max, decimals = 6) {
  // 参数验证
  const minValue = parseFloat(min);
  const maxValue = parseFloat(max);
  
  // 检查参数有效性
  if (isNaN(minValue) || isNaN(maxValue)) {
    console.error(`getRandomAmount收到无效参数: min=${min}, max=${max}`);
    return 0.01; // 返回安全默认值
  }
  
  // 确保min < max
  const actualMin = Math.min(minValue, maxValue);
  const actualMax = Math.max(minValue, maxValue);
  
  // 生成随机数
  const random = Math.random() * (actualMax - actualMin) + actualMin;
  
  // 格式化到指定小数位数
  const result = parseFloat(random.toFixed(decimals));
  
  // 最终检查，确保返回有效数字
  return isNaN(result) || result <= 0 ? actualMin : result;
}

// 修改formatPrice函数
function formatPrice(price) {
  if (!price) return '0';
  if (parseFloat(price) === 0) return '0';

  try {
    const str = price.toString();
    
    // 处理科学计数法
    if (str.includes('e')) {
      const [base, exponent] = str.split('e');
      const exp = parseInt(exponent);
      const sign = base.startsWith('-') ? '-' : '';
      const baseStr = base.replace('.', '').replace('-', '');
      
      if (exp < 0) {
        // 处理小数
        const absExp = Math.abs(exp);
        
        // 找到基数中的小数点位置
        const dotIndex = base.indexOf('.');
        const baseDecimals = dotIndex === -1 ? 0 : base.length - dotIndex - 1;
        
        // 计算需要补充的0的数量
        const zerosNeeded = absExp - baseDecimals;
        
        // 构建结果
        if (zerosNeeded > 0) {
          return `${sign}0.${'0'.repeat(zerosNeeded)}${baseStr}`;
        } else {
          // 如果基数已经有足够的小数位，直接格式化
          const num = parseFloat(base) * Math.pow(10, exp);
          return num.toString();
        }
      } else {
        // 处理大数
        return (parseFloat(base) * Math.pow(10, exp)).toString();
      }
    }
    
    // 对于普通数字，直接返回原始字符串以保持格式
    return str;
    
  } catch (err) {
    console.error('格式化价格失败:', err);
    return price.toString();
  }
}

async function getBNBBalance(provider, address) {
  try {
    const balance = await provider.getBalance(address);
    return ethers.formatUnits(balance, 18);
  } catch (err) {
    console.error("获取BNB余额失败:", err);
    return '0';
  }
}

// 获取钱包的USD1余额
async function getUSD1Balance(provider, walletAddress) {
  try {
    const tokenContract = new ethers.Contract(
      DEFAULT_TOKENS.USD1.address,
      ERC20_ABI,
      provider
    );
    const balance = await tokenContract.balanceOf(walletAddress);
    return ethers.formatUnits(balance, DEFAULT_TOKENS.USD1.decimals);
  } catch (err) {
    console.error("获取USD1余额失败:", err);
    return '0';
  }
}

async function transferBNBFromOtherWallet(provider, fromWallet, toAddress, requiredAmount) {
  try {
    const tx = await fromWallet.sendTransaction({
      to: toAddress,
      value: ethers.parseEther(requiredAmount.toString()),
      gasLimit: 21000
    });
    
    await tx.wait();
    console.log(`从钱包 ${fromWallet.address} 转入 ${requiredAmount} BNB 到 ${toAddress}`);
    return true;
  } catch (err) {
    console.error("BNB转账失败:", err);
    return false;
  }
}

