// 导出为独立工具函数
export const getFistUsdtValue = async (provider, amount) => {
  try {
    // 使用固定的FIST-USDT交易对地址获取价格
    const pairContract = new ethers.Contract(FIST_USDT_PAIR, [
      "function getReserves() external view returns (uint112 reserve0, uint112 reserve1, uint32 blockTimestampLast)",
      "function token0() external view returns (address)"
    ], provider);
    
    const reserves = await pairContract.getReserves();
    const token0 = await pairContract.token0();
    
    // 确定哪个是FIST，哪个是USDT
    const isFistToken0 = token0.toLowerCase() === DEFAULT_TOKENS.FIST.address.toLowerCase();
    
    // 计算1 FIST的USDT价格
    let fistPrice;
    let fistReserve, usdtReserve;
    
    if (isFistToken0) {
      // FIST是token0，USDT是token1
      fistReserve = reserves.reserve0;
      usdtReserve = reserves.reserve1;
    } else {
      // FIST是token1，USDT是token0
      fistReserve = reserves.reserve1;
      usdtReserve = reserves.reserve0;
    }
    
    // 计算实际价格（考虑价格影响）
    if (amount && !isNaN(amount) && amount > 0) {
      // 计算卖出amount数量的FIST得到的USDT数量
      const amountInWei = ethers.parseUnits(amount.toString(), DEFAULT_TOKENS.FIST.decimals);
      
      // 使用恒定乘积公式: (x + dx) * (y - dy) = x * y
      // 计算dy: dy = y * dx / (x + dx)
      const amountOut = (usdtReserve * amountInWei) / (fistReserve + amountInWei);
      
      // 格式化输出
      return ethers.formatUnits(amountOut, DEFAULT_TOKENS.USDT.decimals);
    } else {
      // 简单返回当前市场价格
      fistPrice = ethers.formatUnits(
        (usdtReserve * BigInt(10 ** DEFAULT_TOKENS.FIST.decimals)) / fistReserve,
        DEFAULT_TOKENS.USDT.decimals
      );
      return fistPrice;
    }
  } catch (err) {
    console.error("计算FIST-USDT价值失败:", err);
    return '0';
  }
};

// 通过FIST计算任何代币的USDT价值
export const getTokenUsdtValueViaFist = async (provider, tokenAddress, tokenAmount, tokenDecimals) => {
  try {
    if (!tokenAmount || isNaN(tokenAmount) || tokenAmount <= 0) {
      return 0;
    }
    
    // 1. 获取代币对FIST的价格
    const router = new ethers.Contract(PANCAKE_ROUTER_V2, PANCAKE_ROUTER_ABI, provider);
    const path = [tokenAddress, DEFAULT_TOKENS.FIST.address];
    
    // 计算1个代币能换多少FIST
    const amounts = await router.getAmountsOut(
      ethers.parseUnits('1', tokenDecimals), 
      path
    );
    
    const tokenToFistRate = ethers.formatUnits(amounts[1], DEFAULT_TOKENS.FIST.decimals);
    
    // 2. 计算代币的FIST价值
    const fistValue = parseFloat(tokenAmount) * parseFloat(tokenToFistRate);
    
    // 3. 获取FIST-USDT价格
    const fistUsdtRate = await getFistUsdtValue(provider);
    
    // 4. 计算USDT价值
    return fistValue * parseFloat(fistUsdtRate);
  } catch (err) {
    console.error("通过FIST计算代币USDT价值失败:", err);
    return 0;
  }
};

