// 提供一个异步函数，用于获取最新的USD1-USDT价格
export const fetchUSD1UsdtPrice = async (provider) => {
  try {
    // 通过PancakeSwap路由获取价格
    const router = new ethers.Contract(PANCAKE_ROUTER_V2, PANCAKE_ROUTER_ABI, provider);
    const path = [DEFAULT_TOKENS.USD1.address, DEFAULT_TOKENS.USDT.address];
    
    // 计算1个USD1能换多少USDT
    const amounts = await router.getAmountsOut(
      ethers.parseUnits('1', DEFAULT_TOKENS.USD1.decimals), 
      path
    );
    
    const USD1Price = ethers.formatUnits(amounts[1], DEFAULT_TOKENS.USDT.decimals);
    
    // 更新全局变量
    currentUSD1UsdtRate = formatPrice(USD1Price);
    
    return formatPrice(USD1Price);
  } catch (err) {
    console.error("获取USD1-USDT价格失败:", err);
    return currentUSD1UsdtRate || '0';
  }
};

// 导出为独立工具函数，通过指定的交易对获取USD1价格
export const getUSD1UsdtValue = async (provider, amount) => {
  try {
    // 尝试使用专用交易对获取价格
    if (USD1_USDT_PAIR !== '0x0000000000000000000000000000000000000000') {
      const pairContract = new ethers.Contract(USD1_USDT_PAIR, [
        "function getReserves() external view returns (uint112 reserve0, uint112 reserve1, uint32 blockTimestampLast)",
        "function token0() external view returns (address)"
      ], provider);
      
      const reserves = await pairContract.getReserves();
      const token0 = await pairContract.token0();
      
      // 确定哪个是USD1，哪个是USDT
      const isUSD1Token0 = token0.toLowerCase() === DEFAULT_TOKENS.USD1.address.toLowerCase();
      
      // 计算1 USD1的USDT价格
      let USD1Price;
      let USD1Reserve, usdtReserve;
      
      if (isUSD1Token0) {
        // USD1是token0，USDT是token1
        USD1Reserve = reserves.reserve0;
        usdtReserve = reserves.reserve1;
      } else {
        // USD1是token1，USDT是token0
        USD1Reserve = reserves.reserve1;
        usdtReserve = reserves.reserve0;
      }
      
      // 计算实际价格（考虑价格影响）
      if (amount && !isNaN(amount) && amount > 0) {
        // 计算卖出amount数量的USD1得到的USDT数量
        const amountInWei = ethers.parseUnits(amount.toString(), DEFAULT_TOKENS.USD1.decimals);
        
        // 使用恒定乘积公式: (x + dx) * (y - dy) = x * y
        // 计算dy: dy = y * dx / (x + dx)
        const amountOut = (usdtReserve * amountInWei) / (USD1Reserve + amountInWei);
        
        // 格式化输出
        return ethers.formatUnits(amountOut, DEFAULT_TOKENS.USDT.decimals);
      } else {
        // 简单返回当前市场价格
        USD1Price = ethers.formatUnits(
          (usdtReserve * BigInt(10 ** DEFAULT_TOKENS.USD1.decimals)) / USD1Reserve,
          DEFAULT_TOKENS.USDT.decimals
        );
        return USD1Price;
      }
    } else {
      // 如果没有设置交易对地址，则通过Router获取价格
      return await fetchUSD1UsdtPrice(provider);
    }
  } catch (err) {
    console.error("计算USD1-USDT价值失败:", err);
    return '0';
  }
};

