  // 获取并管理钱包nonce
  const getManagedNonce = async (walletAddress, provider) => {
    const nonceManager = nonceManagerRef.current;
    const nonceLock = nonceLockRef.current;
    
    // 如果这个钱包有锁，等待释放
    while (nonceLock.get(walletAddress)) {
      await new Promise(resolve => setTimeout(resolve, 10));
    }
    
    // 设置锁
    nonceLock.set(walletAddress, true);
    
    try {
      let currentNonce = nonceManager.get(walletAddress);
      
      if (currentNonce === undefined) {
        // 首次获取nonce
        currentNonce = await provider.getTransactionCount(walletAddress, 'pending');
        console.log(`钱包 ${walletAddress} 初始nonce: ${currentNonce}`);
      } else {
        // 使用管理的nonce
        currentNonce += 1;
        console.log(`钱包 ${walletAddress} 使用管理nonce: ${currentNonce}`);
      }
      
      // 更新管理的nonce
      nonceManager.set(walletAddress, currentNonce);
      
      return currentNonce;
    } finally {
      // 释放锁
      nonceLock.set(walletAddress, false);
    }
  };
  
