  // 修改日志记录函数，添加去重功能
  const logTransaction = (txRecord) => {
    // 生成唯一交易ID
    const txId = generateTransactionId(
      txRecord.wallet,
      txRecord.type,
      txRecord.timestamp
    );
    
    // 确保receivedAmount正确格式化显示
    const formattedReceived = txRecord.receivedAmount ? 
      `${typeof txRecord.receivedAmount === 'string' ? 
        (parseFloat(txRecord.receivedAmount) === 0 ? '0.0' : txRecord.receivedAmount) : 
        txRecord.receivedAmount} ${txRecord.receivedSymbol}` : 
      '0.0';
    
    console.log(`[交易记录] ${txRecord.type}:`, {
      wallet: txRecord.wallet,
      amount: txRecord.spentAmount,
      symbol: txRecord.spentSymbol,
      received: formattedReceived,
      targetToken: txRecord.receivedSymbol || '未知代币',
      status: txRecord.status,
      timestamp: txRecord.timestamp,
      txId: txId
    });
    
    // 改进的去重逻辑 - 通过钱包地址和类型识别短时间内的相同交易
    const now = new Date();
    const TIME_WINDOW_MS = 10000; // 10秒内的相同类型交易被视为同一交易
    
    // 首先检查是否有相同的txHash（最精确的匹配）
    const exactMatchIndex = txRecord.txHash ? 
      txHistory.findIndex(tx => 
        tx.txHash === txRecord.txHash && 
        tx.type === txRecord.type && 
        tx.wallet === txRecord.wallet
      ) : -1;
    
    if (exactMatchIndex !== -1) {
      // 找到精确匹配，更新而不是添加
      const updatedHistory = [...txHistory];
      updatedHistory[exactMatchIndex] = {
        ...updatedHistory[exactMatchIndex],
        ...txRecord,
        // 保留原始时间戳，但记录更新时间
        updatedAt: now.toLocaleString()
      };
      setTxHistory(updatedHistory);
      return;
    }
    
    // 检查短时间窗口内的相同钱包和类型的交易
    const timeWindowMatchIndex = txHistory.findIndex(tx => {
      if (tx.wallet !== txRecord.wallet || tx.type !== txRecord.type) {
        return false;
      }
      
      // 计算时间差（毫秒）
      const txTime = new Date(tx.timestamp);
      const timeDiff = Math.abs(now - txTime);
      
      return timeDiff < TIME_WINDOW_MS;
    });
    
    if (timeWindowMatchIndex !== -1) {
      // 找到时间窗口内的匹配，更新而不是添加
      const updatedHistory = [...txHistory];
      // 合并记录，保留最重要的信息
      updatedHistory[timeWindowMatchIndex] = {
        ...updatedHistory[timeWindowMatchIndex],
        ...txRecord,
        // 如果新记录有交易哈希但旧记录没有，使用新的
        txHash: txRecord.txHash || updatedHistory[timeWindowMatchIndex].txHash,
        // 如果新记录有错误信息但旧记录没有，保留错误信息
        error: txRecord.error || updatedHistory[timeWindowMatchIndex].error,
        // 更新状态，优先使用最终状态（失败或已完成）
        status: ['失败', '已完成'].includes(txRecord.status) ? 
               txRecord.status : 
               updatedHistory[timeWindowMatchIndex].status,
        // 保留原始时间戳，但记录更新时间
        updatedAt: now.toLocaleString()
      };
      setTxHistory(updatedHistory);
    } else {
      // 添加新交易记录
      setTxHistory(prev => [{
        ...txRecord,
        createdAt: now.toLocaleString()
      }, ...prev]);
    }
  };

