// ==================== 工具函数 ====================
function formatBigInt(value, decimals = 18) {
  if (!value || value.toString() === '0') return '0';
  try {
    return ethers.formatUnits(value, decimals);
  } catch (err) {
    console.error("格式化BigInt失败:", err);
    return '0';
  }
}

function getRandomAmount(min, max, decimals = 6) {
  const random = Math.random() * (parseFloat(max) - parseFloat(min)) + parseFloat(min);
  return parseFloat(random.toFixed(decimals));
}

// 修改formatPrice函数
function formatPrice(price) {
  if (!price) return '0';
  if (parseFloat(price) === 0) return '0';

  try {
    const str = price.toString();
    
    // 处理科学计数法
    if (str.includes('e')) {
      const [base, exponent] = str.split('e');
      const exp = parseInt(exponent);
      const sign = base.startsWith('-') ? '-' : '';
      const baseStr = base.replace('.', '').replace('-', '');
      
      if (exp < 0) {
        // 处理小数
        const absExp = Math.abs(exp);
        
        // 找到基数中的小数点位置
        const dotIndex = base.indexOf('.');
        const baseDecimals = dotIndex === -1 ? 0 : base.length - dotIndex - 1;
        
        // 计算需要补充的0的数量
        const zerosNeeded = absExp - baseDecimals;
        
        // 构建结果
        if (zerosNeeded > 0) {
          return `${sign}0.${'0'.repeat(zerosNeeded)}${baseStr}`;
        } else {
          // 如果基数已经有足够的小数位，直接格式化
          const num = parseFloat(base) * Math.pow(10, exp);
          return num.toString();
        }
      } else {
        // 处理大数
        return (parseFloat(base) * Math.pow(10, exp)).toString();
      }
    }
    
    // 对于普通数字，直接返回原始字符串以保持格式
    return str;
    
  } catch (err) {
    console.error('格式化价格失败:', err);
    return price.toString();
  }
}

async function getETHBalance(provider, address) {
  try {
    const balance = await provider.getBalance(address);
    return ethers.formatEther(balance);
  } catch (err) {
    console.error("获取ETH余额失败:", err);
    return "0";
  }
}

async function transferETHFromOtherWallet(provider, fromWallet, toAddress, requiredAmount) {
  try {
    const tx = await fromWallet.sendTransaction({
      to: toAddress,
      value: ethers.parseEther(requiredAmount.toString()),
      gasLimit: 21000
    });
    
    await tx.wait();
    console.log(`从钱包 ${fromWallet.address} 转入 ${requiredAmount} ETH 到 ${toAddress}`);
    return true;
  } catch (err) {
    console.error("ETH转账失败:", err);
    return false;
  }
}


