      // 2. 检查合约是否存在
      const contractCode = await rpcProvider.getCode(contractAddress);
      if (contractCode === '0x') {
        return { valid: false, error: '合约不存在或已被销毁' };
      }

      // 3. 尝试创建合约实例并测试基本方法
